window.SDT_TERMS={"b":[{"ko":"벡터","en":"Vector","say":"숫자를 순서대로 늘어놓은 목록. 화살표 하나로 그릴 수 있어요"},{"ko":"차원","en":"Dimension","say":"벡터에 들어 있는 숫자 칸의 개수"},{"ko":"성분","en":"Component","say":"벡터의 한 칸에 들어 있는 숫자"},{"ko":"스칼라","en":"Scalar","say":"칸이 없는 숫자 하나"},{"ko":"원-핫 벡터","en":"One-hot Vector","say":"자기 자리만 1 이고 나머지는 모두 0 인 벡터"},{"ko":"단어 벡터","en":"Word Vector","say":"단어의 지도 좌표. 뜻이 비슷하면 가까이 살아요"},{"ko":"임베딩","en":"Embedding","say":"토큰을 숫자 벡터로 바꾼 것"},{"ko":"내적","en":"Dot Product","say":"같은 자리끼리 곱해서 모두 더하기"},{"ko":"노름","en":"Norm","say":"벡터 화살표의 길이"},{"ko":"단위 벡터","en":"Unit Vector","say":"길이가 정확히 1 인 벡터"},{"ko":"코사인 유사도","en":"Cosine Similarity","say":"두 화살표가 얼마나 같은 쪽을 보는지 0 과 1 사이로"},{"ko":"어텐션 점수","en":"Attention Score","say":"두 벡터가 얼마나 관련 있는지 나타낸 날것 숫자"},{"ko":"행렬","en":"Matrix","say":"숫자를 가로 세로 표로 늘어놓은 것"},{"ko":"모양","en":"Shape","say":"행이 몇 줄이고 열이 몇 칸인지"},{"ko":"행렬 곱","en":"Matrix Multiplication","say":"표와 표를 곱해서 새 표를 만드는 계산"},{"ko":"전치","en":"Transpose","say":"표를 눕혀서 행과 열을 바꾸는 것"},{"ko":"텐서","en":"Tensor","say":"PyTorch 가 쓰는 숫자 덩어리. 벡터와 행렬을 아우르는 말"},{"ko":"지수 함수","en":"Exponential Function","say":"exp 를 씌워 항상 양수로 만드는 함수"},{"ko":"로그","en":"Logarithm","say":"몇 번 곱했는지를 되묻는 함수"},{"ko":"자연로그","en":"Natural Logarithm","say":"밑이 e 인 로그. 코드에서 log 라고 하면 보통 이것"},{"ko":"음의 로그","en":"Negative Log","say":"로그에 마이너스를 붙인 것. 확률이 작을수록 커져요"},{"ko":"확률","en":"Probability","say":"일이 얼마나 자주 일어나는지를 0 과 1 사이 숫자로"},{"ko":"퍼플렉서티","en":"Perplexity (PPL)","say":"다음 단어를 고를 때 헷갈리는 후보가 평균 몇 개인지"},{"ko":"확률 분포","en":"Probability Distribution","say":"후보마다 확률을 붙여 둔 목록. 다 더하면 1"},{"ko":"조건부 확률","en":"Conditional Probability","say":"무엇이 이미 주어졌을 때의 확률"},{"ko":"곱의 규칙","en":"Product Rule","say":"여러 일이 잇따라 일어날 확률은 곱해서 구해요"},{"ko":"말뭉치","en":"Corpus","say":"학습에 쓰는 글을 잔뜩 모아 둔 것"},{"ko":"언어 모델","en":"Language Model (LM)","say":"다음 토큰을 맞히는 모델"},{"ko":"소프트맥스","en":"Softmax","say":"점수를 모두 더해 1 이 되는 확률 파이로 나누기"},{"ko":"교차 엔트로피","en":"Cross-Entropy","say":"정답에 준 확률의 음의 로그를 벌점으로 쓰는 손실"},{"ko":"손실 함수","en":"Loss Function","say":"틀린 정도를 매기는 벌점"},{"ko":"함수","en":"Function","say":"넣으면 하나가 나오는 상자"},{"ko":"미분","en":"Derivative","say":"살짝 움직였을 때 결과가 얼마나 바뀌는지"},{"ko":"기울기","en":"Gradient","say":"손실이 가장 빨리 커지는 방향과 그 가파름"},{"ko":"접선","en":"Tangent Line","say":"곡선의 한 점에 살짝 붙인 직선"},{"ko":"편미분","en":"Partial Derivative","say":"다른 것은 고정하고 하나만 움직여 본 미분"},{"ko":"연쇄 법칙","en":"Chain Rule","say":"맞물린 톱니바퀴처럼 미분을 곱해 이어 붙이는 규칙"},{"ko":"경사 하강법","en":"Gradient Descent","say":"안개 낀 산에서 발밑 기울기만 보고 한 걸음씩 내려가기"},{"ko":"학습률","en":"Learning Rate","say":"한 걸음의 보폭"},{"ko":"파라미터","en":"Parameter","say":"학습하면서 바뀌는 숫자. 모델이 기억을 저장하는 자리"},{"ko":"확률적 경사 하강법","en":"Stochastic Gradient Descent (SGD)","say":"전체가 아니라 조금만 보고 한 걸음 내려가기"},{"ko":"미니배치","en":"Minibatch","say":"전체가 아니라 몇 개만 묶어서 한 번에 보는 것"},{"ko":"에폭","en":"Epoch","say":"학습 데이터를 처음부터 끝까지 한 번 다 본 것"},{"ko":"뉴런","en":"Neuron","say":"여러 숫자를 가중합하고 구부려 하나로 내보내는 작은 계산 단위"},{"ko":"가중합","en":"Weighted Sum","say":"값마다 가중치를 곱해서 모두 더한 것"},{"ko":"편향 항","en":"Bias Term","say":"가중합에 마지막으로 더해 주는 한 숫자"},{"ko":"활성화 함수","en":"Activation Function","say":"가중합을 한 번 구부려 주는 함수"},{"ko":"비선형성","en":"Nonlinearity","say":"곧은 직선이 아닌 구부러진 변환"},{"ko":"렐루","en":"ReLU","say":"음수는 0 으로 만들고 양수는 그대로 두는 함수"},{"ko":"시그모이드","en":"Sigmoid","say":"어떤 수든 0 과 1 사이로 눌러 주는 S자 함수"},{"ko":"층","en":"Layer","say":"뉴런을 한 줄로 모아 놓은 묶음"},{"ko":"다층 퍼셉트론","en":"Multi-Layer Perceptron (MLP)","say":"뉴런 층을 여러 겹 쌓은 가장 기본 신경망"},{"ko":"순전파","en":"Forward Pass","say":"입력에서 출력까지 앞으로 한 번 계산하기"},{"ko":"변수","en":"Variable","say":"값에 이름표를 붙여 두는 것"},{"ko":"리스트","en":"List","say":"파이썬에서 순서대로 담는 상자. 대괄호로 써요"},{"ko":"튜플","en":"Tuple","say":"한 번 만들면 못 바꾸는 목록. 소괄호로 써요"},{"ko":"딕셔너리","en":"Dictionary","say":"이름표(키)로 값을 꺼내는 파이썬 상자"},{"ko":"반복문","en":"For Loop","say":"같은 일을 목록의 원소마다 되풀이하기"},{"ko":"함수 정의","en":"Function Definition","say":"def 로 내가 쓸 계산에 이름을 붙이는 것"},{"ko":"자동 미분","en":"Automatic Differentiation (Autodiff)","say":"미분을 사람 대신 컴퓨터가 해 주는 기능"}],"1":[{"ko":"자연어처리","en":"Natural Language Processing (NLP)","say":"컴퓨터가 사람 말을 처리하고, 이해하고, 만들어 내게 하는 분야","more":"자연어 이해(NLU)와 자연어 생성(NLG) 두 방향을 합친 말이에요. 말을 잘 다루는 기계가 똑똑해 보여서 AI 의 한가운데 있어요."},{"ko":"자연어 이해","en":"Natural Language Understanding (NLU)","say":"글에서 뜻(의도, 개체, 사실)을 뽑아내는 쪽","more":"분류, 정보 뽑기, 검색, 질문에 답하기가 여기에 들어가요. 방향은 글 → 뜻이에요."},{"ko":"자연어 생성","en":"Natural Language Generation (NLG)","say":"뜻에서 새 글을 만들어 내는 쪽","more":"글쓰기, 요약, 응답이 여기에 들어가요. 방향은 뜻 → 글이에요."},{"ko":"중의성","en":"Ambiguity","say":"같은 글자가 여러 뜻으로 읽히는 성질","more":"단어(배, bank), 구조(I saw a man with a telescope), 띄어쓰기(아버지가방에) 수준이 있어요. NLP 의 핵심 난제예요."},{"ko":"교착어","en":"Agglutinative Language","say":"어간에 작은 조각을 붙여 한 단어를 만드는 언어, 한국어가 대표","more":"먹- + -었- + -겠- + -더라 → 먹었겠더라처럼요. 그래서 한국어 동사는 형태가 수천 가지예요."},{"ko":"형태소","en":"Morpheme","say":"뜻을 가진 가장 작은 말의 조각","more":"먹었겠더라는 먹-, -었-, -겠-, -더라 네 형태소로 이루어져요."},{"ko":"형태소 분석기","en":"Morphological Analyzer","say":"단어를 형태소로 쪼개 주는 도구","more":"한국어는 형태소가 많이 붙어서 형태소 분석이 특히 중요해요. 2주차 토큰화와 이어져요."},{"ko":"말뭉치","en":"Corpus","say":"컴퓨터가 배우려고 모아 둔 아주 많은 글 묶음","more":"통계 시대(2막)부터 말뭉치에서 패턴을 세는 방식이 중심이 됐어요."},{"ko":"토큰","en":"Token","say":"글을 컴퓨터가 다루는 작은 조각으로 자른 것","more":"레고 조각에 비유해요. 단어일 수도, 단어 조각일 수도 있어요. 2주차에 자세히 배워요."},{"ko":"토큰화","en":"Tokenization","say":"글을 토큰으로 자르는 일","more":"과목 주문의 첫 단계예요. 2주차 주제예요."},{"ko":"엔그램","en":"n-gram","say":"바로 앞 몇 단어만 보고 다음 단어를 맞히는 세기 방법","more":"n 개씩 붙은 단어 묶음을 말해요. 1-gram 은 한 단어, 2-gram 은 두 단어. 3주차에 직접 만들어요."},{"ko":"언어 모델","en":"Language Model (LM)","say":"다음에 올 단어(토큰)를 맞히는 모델","more":"휴대폰 자판의 다음 단어 추천과 같아요. P(다음 단어 | 앞 단어들)을 계산해요."},{"ko":"워드투벡","en":"word2vec","say":"단어를 벡터(지도 좌표)로 바꾸는 2013년 방법","more":"라벨 없이 날 글에서, 주변 단어로 뜻을 배워요. king - man + woman ≈ queen 같은 뜻의 산수가 돼요."},{"ko":"단어 벡터","en":"Word Vector","say":"단어를 숫자 목록으로 나타낸 것, 단어의 지도 좌표","more":"뜻이 비슷한 단어는 가까운 벡터가 돼요."},{"ko":"분포 가설","en":"Distributional Hypothesis","say":"'친구를 보면 그 사람을 안다' 처럼, 주변 단어로 단어 뜻을 안다는 생각","more":"Firth(1957)의 'You shall know a word by the company it keeps' 가 대표 문장이에요."},{"ko":"순환 신경망","en":"Recurrent Neural Network (RNN)","say":"문장을 한 단어씩 읽으며 메모장(은닉 상태)을 고쳐 쓰는 신경망","more":"매 단계 같은 부품을 다시 써요. 3주차에 자세히 배워요."},{"ko":"장단기 메모리","en":"LSTM","say":"RNN 을 고쳐서 긴 문장도 더 잘 기억하게 한 신경망","more":"게이트로 무엇을 기억하고 잊을지 정해요. 1990년대에 나왔어요."},{"ko":"은닉 상태","en":"Hidden State","say":"RNN 이 지금까지 읽은 내용을 요약해 들고 있는 메모장","more":"한 단어를 읽을 때마다 새로 고쳐 써요."},{"ko":"시퀀스-투-시퀀스","en":"seq2seq","say":"문장을 받아 다른 문장을 내놓는 구조(2014)","more":"인코더가 원문을 압축하고 디코더가 결과 문장을 써요. 기계 번역에서 나왔어요."},{"ko":"어텐션","en":"Attention","say":"결과를 만들 때 입력 중 지금 중요한 부분에 주목하는 방법","more":"2015년 seq2seq 번역에서 나왔고, 2017년 트랜스포머의 핵심이 됐어요. 4주차 주제예요."},{"ko":"트랜스포머","en":"Transformer","say":"어텐션만으로 만든 신경망 구조(2017)","more":"순환 없이 모든 단어를 병렬로 처리해서 GPU 로 크게 키우기 좋아요. 요즘 LLM 의 뼈대예요."},{"ko":"사전 학습","en":"Pre-training","say":"라벨 없는 거대한 글로 먼저 언어를 익히는 단계","more":"한 번 사전 학습한 모델을 여러 일에 싸게 맞춰 써요. BERT, GPT(2018)가 대표예요."},{"ko":"사후 학습","en":"Post-training","say":"사전 학습 뒤 사람이 원하는 대로 모델을 다듬는 단계","more":"지시 학습, RLHF 같은 방법이 들어가요. 7주차 주제예요."},{"ko":"대규모 언어 모델","en":"Large Language Model (LLM)","say":"아주 많은 글로 학습한 아주 큰 언어 모델","more":"ChatGPT, Claude, EXAONE 같은 모델이에요. 프롬프트 하나로 여러 NLP 일을 해요."},{"ko":"파라미터","en":"Parameter","say":"모델이 학습하며 스스로 맞춰 가는 숫자들","more":"개수가 모델 크기예요. GPT-3 는 175B(1,750억) 개예요."},{"ko":"분류","en":"Classification","say":"글 하나에 라벨 하나를 붙이는 일","more":"스팸/정상, 긍정/부정, 주제 가르기가 대표예요."},{"ko":"개체명 인식","en":"Named Entity Recognition (NER)","say":"글 속에서 사람, 장소, 날짜 같은 이름 붙은 것을 찾는 일","more":"토큰마다 태그를 붙이는 시퀀스 레이블링의 한 종류예요."},{"ko":"합성곱 신경망","en":"Convolutional Neural Network (CNN)","say":"작은 창을 밀며 특징을 잡는 신경망","more":"이미지에서 유명하지만 글에도 써요. 3주차에 나와요."},{"ko":"튜링 테스트","en":"Turing Test","say":"기계와 대화해 보고 사람인지 기계인지 가리는 지능 시험","more":"1950년 앨런 튜링이 'Can machines think?' 를 물으며 제안했어요."},{"ko":"엘리자","en":"ELIZA","say":"1966년 MIT 의 최초 챗봇","more":"패턴 규칙 약 200개로 심리 상담사를 흉내 냈어요. 뜻도 기억도 없었지만 사람들은 속마음을 털어놨어요."},{"ko":"조지타운-IBM 시연","en":"Georgetown-IBM Experiment","say":"1954년 러시아어 60문장을 영어로 번역해 보인 시연","more":"'5년 안에 번역 해결' 을 장담했지만 틀렸어요."},{"ko":"기계 번역","en":"Machine Translation (MT)","say":"컴퓨터가 한 언어를 다른 언어로 옮기는 일","more":"1947 위버의 '번역 = 암호 풀기' 에서 시작해 2016년 구글 번역의 신경망 전환까지 이어져요."},{"ko":"ALPAC 보고서","en":"ALPAC Report","say":"1966년 기계 번역이 약속보다 훨씬 어렵다고 결론 낸 미국 보고서","more":"그 뒤 미국 연구 지원이 약 10년 동안 끊겨 'AI 겨울' 이 왔어요."},{"ko":"다트머스 워크숍","en":"Dartmouth Workshop","say":"1956년 여름, 인공지능이라는 이름이 생긴 모임","more":"사진 맨 오른쪽이 섀넌이에요."},{"ko":"인공지능","en":"Artificial Intelligence (AI)","say":"사람처럼 생각하고 배우는 기계를 만드는 분야","more":"1956년 다트머스 워크숍에서 이름이 생겼어요."},{"ko":"규칙 기반 방법","en":"Rule-based Approach","say":"사람이 규칙을 손으로 써서 말을 처리하는 방법(1막)","more":"ELIZA, SHRDLU 가 예예요. 언어는 규칙으로 다 적을 수 없어서 한계에 부딪혔어요."},{"ko":"통계 기반 방법","en":"Statistical Approach","say":"규칙 대신 많은 글에서 패턴을 세어 확률로 처리하는 방법(2막)","more":"n-gram, IBM 통계 번역이 대표예요. 뜻을 모른다는 벽이 있었어요."},{"ko":"잡음 채널 모델","en":"Noisy Channel Model","say":"잡음 낀 통로를 지나 망가진 메시지를 확률로 원래대로 되돌리는 생각","more":"섀넌(1948)의 정보 이론에서 나왔고, 통계 번역과 음성 인식의 설계도가 됐어요."},{"ko":"신경망","en":"Neural Network","say":"숫자를 여러 층으로 계산하며 데이터에서 규칙을 배우는 모델","more":"3막부터 NLP 의 주인공이에요. 기초 다지기 9단원에서 자세히 봐요."},{"ko":"인코더","en":"Encoder","say":"원문을 읽고 요약(압축)하는 부분","more":"seq2seq 에서 원문 쪽을 맡아요."},{"ko":"디코더","en":"Decoder","say":"요약을 받아 결과 문장을 한 단어씩 쓰는 부분","more":"seq2seq 에서 번역문 쪽을 맡아요. 어텐션으로 원문을 다시 봐요."},{"ko":"미세 조정","en":"Fine-tuning","say":"사전 학습한 모델을 작은 데이터로 특정 일에 맞추는 것","more":"감성 분석, 질의응답, 번역 같은 일마다 적은 데이터만 있으면 돼요."},{"ko":"스케일링 법칙","en":"Scaling Laws","say":"파라미터, 데이터, 계산을 늘리면 성능이 예측 가능하게 좋아진다는 법칙","more":"그래서 모델을 계속 키웠고, 4년에 약 5,700배 커졌어요."},{"ko":"문맥 내 학습","en":"In-context Learning","say":"모델을 다시 학습시키지 않고 프롬프트 속 예시만 보고 일을 해내는 능력","more":"GPT-3(2020)가 보여 줬어요. 예시 몇 개를 주는 퓨샷 방식이 대표예요."},{"ko":"지시 학습","en":"Instruction Tuning","say":"지시문을 따르도록 모델을 추가로 학습시키는 것","more":"ChatGPT(2022)가 RLHF 와 함께 썼어요."},{"ko":"인간 피드백 강화 학습","en":"RLHF","say":"사람이 더 좋다고 고른 답 쪽으로 모델을 다듬는 방법","more":"Reinforcement Learning from Human Feedback 의 줄임말이에요. 사후 학습의 한 방법이에요."},{"ko":"","en":"BERT","say":"2018년 나온 사전 학습 언어 모델","more":"GPT 와 함께 '한 번 배워 어디서나 쓰기' 시대를 연 두 반쪽이에요. 5주차에 배워요."},{"ko":"","en":"GPT","say":"2018년부터 나온 다음 단어를 맞히며 사전 학습한 언어 모델 계열","more":"GPT-3(2020)는 문맥 내 학습을, ChatGPT(2022)는 대화 서비스를 보여 줬어요."},{"ko":"","en":"ChatGPT","say":"2022년 11월 공개된 대화형 LLM 서비스","more":"지시 학습과 RLHF 를 더했고, 두 달 만에 사용자 1억 명을 모았어요."},{"ko":"엑사원","en":"EXAONE","say":"LG AI연구원의 한국어 대규모 언어 모델","more":"교수님이 개발에 참여했다고 소개한 모델이에요. HyperCLOVA X 와 함께 한국어 LLM 의 예예요."},{"ko":"화용론","en":"Pragmatics","say":"같은 말이 상황에 따라 다른 뜻이 되는 것을 다루는 분야","more":"'잘~한다' 가 칭찬인지 비꼼인지 가리는 문제예요."},{"ko":"생략","en":"Ellipsis","say":"문장에서 맥락으로 알 수 있는 말을 빼는 것","more":"'밥 먹었어?' 에는 주어도 목적어도 없어요. 한국어에 특히 많아요."},{"ko":"지시 대상","en":"Reference","say":"'그것', 'it' 같은 말이 가리키는 대상","more":"트로피 문장처럼 세상 지식이 있어야 찾을 수 있을 때가 많아요."},{"ko":"위노그라드 스키마","en":"Winograd Schema","say":"한 단어만 바꾸면 it 이 가리키는 대상이 뒤집히는 문장 시험","more":"big 이면 트로피, small 이면 가방. 문법이 아니라 세상 지식을 시험해요."},{"ko":"높임법","en":"Honorifics","say":"말하는 상대에 따라 높여 말하는 한국어 문법","more":"먹어 / 드세요 / 잡수세요는 같은 사실, 다른 사회적 뜻이에요."},{"ko":"저자원 자연어처리","en":"Low-resource NLP","say":"데이터가 아주 적은 언어를 다루는 NLP","more":"지구의 7,000개 넘는 언어 대부분이 여기에 들어가요."},{"ko":"시퀀스 레이블링","en":"Sequence Labeling","say":"문장 속 토큰마다 태그를 하나씩 붙이는 일","more":"품사 태깅, 개체명 인식이 대표예요."},{"ko":"품사 태깅","en":"Part-of-Speech Tagging (POS)","say":"단어마다 명사, 동사 같은 품사를 붙이는 일","more":"시퀀스 레이블링의 대표 예예요. 통계 시대에도 쓰였어요."},{"ko":"감성 분석","en":"Sentiment Analysis","say":"글이 긍정인지 부정인지 가리는 일","more":"분류의 대표 예예요."},{"ko":"검색 증강 생성","en":"Retrieval-Augmented Generation (RAG)","say":"먼저 관련 자료를 찾아 오고, 그걸 근거로 답을 만들게 하는 방법","more":"10주차 주제예요. 교수님 연구실의 주요 연구 주제이기도 해요."},{"ko":"에이전트","en":"Agent","say":"도구를 쓰고 계획을 세워 여러 단계 일을 해내는 LLM 시스템","more":"11주차 주제예요."},{"ko":"파이토치","en":"PyTorch","say":"신경망을 만들고 학습시키는 파이썬 도구","more":"이 수업의 실습 도구예요."},{"ko":"허깅 페이스","en":"Hugging Face","say":"사전 학습된 모델을 쉽게 받아 쓰게 해 주는 도구와 모임","more":"transformers 라이브러리를 만들었고, 주교재도 이 팀이 썼어요."},{"ko":"텀 프로젝트","en":"Term Project","say":"팀으로 한 학기 동안 하는 프로젝트","more":"성적의 25%예요. 8주차에 제안 발표, 학기 말에 결과와 보고서를 내요."},{"ko":"프로그래밍 과제","en":"Programming Assignment","say":"파이썬으로 직접 코드를 짜는 과제","more":"성적의 40%예요. 파이토치, 트랜스포머 구현, RAG, 에이전트, 평가가 들어가요."},{"ko":"기말고사","en":"Final Exam","say":"16주차 시험. 성적의 30%예요."},{"ko":"자연어","en":"Natural Language","say":"사람이 자라면서 쓰는 말. 한국어, 영어 같은 것이에요. 파이썬 같은 인공 언어는 아니에요."},{"ko":"저자원 언어","en":"Low-resource Language","say":"학습할 데이터가 거의 없는 언어예요. 지구의 7,000 개 넘는 언어 대부분이에요."},{"ko":"형태소 분석","en":"Morphological Analysis","say":"어절을 형태소로 나누는 일이에요. 한국어 NLP 에서 중요해요."},{"ko":"띄어쓰기","en":"Spacing","say":"낱말 사이의 빈칸. 실제 글에서는 잘 안 지켜지고, 틀리면 뜻이 바뀌어요."}],"2":[{"ko":"단어 벡터","en":"Word Vector","say":"단어 하나를 숫자 여러 개로 적은 지도 좌표","more":"뜻이 비슷한 단어는 가까운 좌표에 살게 만든 숫자 목록이에요. 2강 뒷부분(word2vec)에서 자세히 배워요."},{"ko":"토큰화","en":"Tokenization","say":"글을 토큰 조각으로 자르는 일","more":"모든 NLP 시스템이 가장 먼저 내리는 결정이에요. 어떻게 자르느냐가 품질, 비용, 여러 언어 실력을 좌우해요."},{"ko":"토큰","en":"Token","say":"모델이 글을 받는 가장 작은 조각, 레고 조각 하나","more":"단어일 수도, 글자일 수도, 그 사이 조각(서브워드)일 수도 있어요. 요즘 모델은 서브워드 조각을 써요."},{"ko":"교착어","en":"Agglutinative Language","say":"줄기에 문법 조각을 줄줄이 붙여 한 단어를 만드는 언어","more":"한국어, 일본어가 그래요. '먹었겠더라' 처럼 형태소 여러 개가 한 어절에 붙어서, 띄어쓰기로 자르면 어휘가 폭발해요."},{"ko":"자연어처리","en":"Natural Language Processing (NLP)","say":"컴퓨터가 사람 말을 알아듣고 만들어 내게 하는 분야","more":"글과 말을 컴퓨터가 다루게 하는 인공지능 분야예요. 요즘은 글을 토큰으로 자르고, 벡터로 바꾸고, 다음 토큰을 맞히는 흐름으로 풀어요."},{"ko":"대규모 언어 모델","en":"Large Language Model (LLM)","say":"아주 많은 글로 다음 토큰 맞히기를 배운 거대한 모델","more":"GPT, Claude, Llama, EXAONE 같은 모델이에요. 모두 서브워드 토큰으로 글을 잘라서 받아요."},{"ko":"다음 토큰 예측","en":"Next Token Prediction","say":"지금까지 나온 토큰을 보고 바로 다음 토큰을 맞히는 일","more":"현대 NLP 파이프라인의 마지막 화살표예요. 글 → 토큰 → 벡터 → 다음 토큰 예측."},{"ko":"바이트 쌍 인코딩","en":"Byte Pair Encoding (BPE)","say":"자주 붙어 다니는 두 조각을 한 조각으로 접착하기를 되풀이하는 방법","more":"글자에서 시작해서 가장 자주 붙어 나오는 쌍을 합치고 규칙을 적어요. 이것을 목표 어휘 크기까지 되풀이해요. 1994년 압축 방법을 2016년에 NLP로 가져왔어요."},{"ko":"토큰 ID","en":"Token ID","say":"어휘 목록에서 그 토큰이 몇 번째인지 적은 번호","more":"신경망은 글자를 못 먹고 [8203, 318, ...] 같은 정수 번호 줄을 먹어요. 번호마다 벡터가 하나씩 붙어 있어요."},{"ko":"토크나이저","en":"Tokenizer","say":"글 → 토큰 줄 → 번호 줄로 바꿔 주는 도구","more":"컴퓨터가 보는 바이트와 신경망이 먹는 번호 사이의 다리예요. 말뭉치로 학습해서 만들어요."},{"ko":"어휘","en":"Vocabulary","say":"레고 상자에 든 조각 종류 목록","more":"모델이 아는 토큰 전체 목록이에요. 목록에 없는 것은 원래 [UNK] 가 돼요. GPT-2 는 약 5만 개, GPT-4o 는 약 20만 개예요."},{"ko":"","en":"UTF-8","say":"글자를 바이트 숫자로 바꾸는 세계 공통 약속","more":"영어 글자는 1바이트, 한글 한 글자는 3바이트가 돼요. 컴퓨터가 실제로 저장하는 것은 이 바이트예요."},{"ko":"미등록 단어","en":"Out-of-Vocabulary (OOV)","say":"어휘 목록에 없는 단어","more":"단어 단위로 자르면 신조어, 오타, 이름이 전부 미등록 단어가 되어 [UNK] 로 뭉개져요."},{"ko":"미지 토큰","en":"[UNK]","say":"'모르는 것' 이라는 뜻의 대체 토큰","more":"어휘에 없는 단어를 받으면 이 토큰 하나로 바꿔 버려요. 원래 뜻이 전부 사라져요."},{"ko":"말뭉치","en":"Corpus","say":"학습에 쓰는 아주 큰 글 뭉치","more":"토크나이저도, 단어 벡터도 말뭉치를 보고 배워요. 말뭉치에 어떤 언어가 많은지가 결과를 바꿔요."},{"ko":"지프의 법칙","en":"Zipf's Law","say":"몇 개 단어만 아주 자주 나오고 대부분은 거의 안 나온다는 법칙","more":"빈도가 순위에 반비례해요(빈도 ∝ 1/순위). 그래서 어휘를 아무리 크게 해도 긴 꼬리가 잘려서 [UNK] 가 돼요."},{"ko":"어텐션","en":"Attention","say":"문장 안의 토큰끼리 서로 얼마나 볼지 정하는 장치","more":"트랜스포머의 핵심이에요. 계산량이 길이의 제곱으로 늘어서, 토큰 줄이 길어지면 비용이 크게 늘어요."},{"ko":"서브워드","en":"Subword","say":"단어와 글자 사이 크기의 조각","more":"자주 나오는 덩어리는 통째로, 드문 단어는 조각으로 잘라요. 미등록 단어가 없고, 길이도 적당하고, 조각에 뜻도 있어요."},{"ko":"병합 규칙","en":"Merge Rule","say":"'이 두 조각을 붙여라' 라는 접착 순서 한 줄","more":"BPE 가 배우는 것은 순서가 있는 병합 규칙 목록이에요. 그 목록이 곧 토크나이저예요. 새 글도 같은 순서로 다시 붙여요."},{"ko":"바이트 수준 BPE","en":"Byte-level BPE","say":"글자 대신 256가지 바이트에서 출발하는 BPE","more":"GPT-2 부터 표준이에요. 어떤 입력이든 바이트로 쪼갤 수 있어서 [UNK] 가 아예 생기지 않아요."},{"ko":"워드피스","en":"WordPiece","say":"말뭉치를 가장 잘 설명하는 쌍을 붙이는 BERT 의 방법","more":"그냥 빈도가 아니라 우도를 가장 많이 올리는 쌍을 합쳐요. 뒤에 붙는 조각에는 ## 를 달아요(play + ##ing)."},{"ko":"유니그램 토크나이저","en":"Unigram","say":"큰 후보 목록에서 시작해 쓸모없는 조각을 깎아 내는 방법","more":"BPE 와 방향이 반대예요. 문장마다 확률이 가장 높은 자르기를 골라요."},{"ko":"우도","en":"Likelihood","say":"이 설명이 데이터를 얼마나 그럴듯하게 만드는지 재는 값","more":"워드피스는 합쳤을 때 말뭉치가 더 그럴듯해지는(우도가 오르는) 쌍을 골라요. 따로는 드문데 늘 붙어 나오는 쌍을 좋아해요."},{"ko":"센텐스피스","en":"SentencePiece","say":"BPE 나 유니그램을 담아 둔 토큰화 도구 모음","more":"띄어쓰기도 ▁ 기호 하나로 다뤄서, 띄어쓰기가 들쭉날쭉한 한국어, 일본어에 좋아요. 알고리즘 이름이 아니라 라이브러리예요."},{"ko":"특수 토큰","en":"Special Token","say":"모델 행동을 바꾸는 스위치 같은 약속 토큰","more":"<|endoftext|>, [CLS], [SEP], 채팅 틀 토큰 같은 것이에요. 글 끝, 문장 경계, 대화 차례를 알려 줘요."},{"ko":"컨텍스트 창","en":"Context Window","say":"모델이 한 번에 볼 수 있는 토큰 수의 한도","more":"API 요금과 이 한도는 모두 토큰 수로 세요. 같은 뜻을 적은 토큰으로 담을수록 싸고 더 많이 담아요."},{"ko":"형태소","en":"Morpheme","say":"뜻을 가진 가장 작은 말 조각","more":"'먹었겠더라' 는 먹-(먹다), -었-(과거), -겠-(추측), -더라(회상) 네 형태소예요."},{"ko":"어절","en":"","say":"띄어쓰기로 나뉘는 한국어 한 덩어리","more":"'자연어처리는' 처럼 단어에 조사, 어미가 붙은 덩어리예요. 한국어에서 '공백 단어' 는 곧 어절이에요."},{"ko":"형태소 분석기","en":"Morphological Analyzer","say":"언어 지식으로 어절을 형태소로 자르고 품사를 붙이는 도구","more":"MeCab-ko, Kiwi, Okt, Komoran 이 대표예요. 깔끔하지만 규칙 기반이라 신조어에 약하고 실수가 뒤로 번져요."},{"ko":"품사 태그","en":"POS Tag","say":"형태소마다 붙이는 품사 이름표","more":"NNG(일반 명사), JX(보조사), VA(형용사), EF(종결 어미) 같은 표시예요."},{"ko":"토큰 과다 분할","en":"Fertility","say":"단어 하나가 평균 몇 토큰으로 잘리는지 재는 값","more":"토큰 수 ÷ 공백 단어 수예요. 클수록 그 언어를 비싸게 다룬다는 뜻이에요. 영어 중심 토크나이저에서 한국어는 2~3배 커져요."},{"ko":"워드투벡","en":"word2vec","say":"주변 단어를 맞히는 연습으로 단어 벡터를 배우는 방법","more":"2013년 Mikolov 등이 낸 틀이에요. 라벨 없이 큰 말뭉치 하나만 있으면 되고, 예측은 수단, 벡터가 목표예요."},{"ko":"워드넷","en":"WordNet","say":"사람이 손으로 만든 영어 유의어, 상하위어 사전","more":"동의어 묶음과 'is-a' 계층(판다 ⊂ 곰 ⊂ 포유류)을 담았어요. 뉘앙스, 신조어, 유사도 숫자를 다루지 못해요."},{"ko":"시소러스","en":"Thesaurus","say":"동의어, 반의어, 상하위어를 모아 정리한 사전","more":"워드넷이 대표적인 시소러스예요. 사람이 규칙처럼 정리한 것이라 계산 가능한 뜻이 되지 못해요."},{"ko":"원-핫 벡터","en":"One-hot Vector","say":"한 칸만 1이고 나머지는 모두 0인 벡터","more":"어휘 크기만큼 칸이 필요하고 거의 다 0이라 희소해요. 서로 다른 두 단어의 내적은 항상 0이라 비슷함을 못 나타내요."},{"ko":"직교","en":"Orthogonal","say":"두 벡터가 서로 직각이라 내적이 0인 상태","more":"원-핫 벡터는 모든 쌍이 직교해요. 그래서 motel 과 hotel 도 '전혀 안 비슷함'으로 나와요."},{"ko":"분포 가설","en":"Distributional Hypothesis","say":"단어의 뜻은 그 단어 주변에 자주 오는 단어들로 알 수 있다는 생각","more":"Firth(1957)의 'You shall know a word by the company it keeps' 로 유명해요. word2vec, BERT, GPT 모두 이 생각 위에 서 있어요."},{"ko":"분포 의미론","en":"Distributional Semantics","say":"단어의 뜻을 그 단어가 나타나는 문맥들의 모음으로 보는 방법","more":"banking 의 뜻을 알고 싶으면 banking 이 나온 수천 개 문장을 보는 식이에요. 사전도 라벨도 필요 없어요."},{"ko":"임베딩","en":"Embedding","say":"단어 벡터를 부르는 다른 이름","more":"word vector, (word) embedding, word representation 은 모두 같은 것이에요. 교수님은 임베딩이라는 말을 가장 많이 쓴대요."},{"ko":"밀집 벡터","en":"Dense Vector","say":"칸 수는 적고 칸마다 의미 있는 실수가 차 있는 벡터","more":"원-핫 벡터처럼 수십만 칸에 0만 가득한 대신, 수백 칸에 모두 값이 들어 있어요."},{"ko":"희소 벡터","en":"Sparse Vector","say":"칸 대부분이 0인 벡터","more":"원-핫 벡터가 대표예요. 칸 수가 어휘 크기만큼 커서 저장 공간이 많이 들고 표현력도 약해요."},{"ko":"내적","en":"Dot Product","say":"같은 자리 숫자끼리 곱해서 모두 더한 값","more":"두 화살표가 같은 쪽을 볼수록 커요. word2vec 에서 '얼마나 비슷한가' 점수로 써요."},{"ko":"코사인 유사도","en":"Cosine Similarity","say":"두 벡터가 가리키는 방향이 얼마나 같은지 -1~1로 나타낸 값","more":"내적을 두 벡터 길이의 곱으로 나눈 값이에요. 길이 영향을 빼고 방향만 봐요."},{"ko":"중심 단어","en":"Center Word","say":"지금 창 한가운데에 있는 주인공 단어 c","more":"위치 t 의 단어 $w_t$ 예요. 스킵그램에서는 중심 단어가 주변 단어를 맞혀요."},{"ko":"문맥 단어","en":"Context Word","say":"중심 단어 양옆 창 안에 있는 이웃 단어 o","more":"윈도우 크기가 m 이면 왼쪽 m 개, 오른쪽 m 개예요. $w_{t+j}$ 로 적어요."},{"ko":"윈도우","en":"Window","say":"중심 단어 양옆으로 몇 칸까지 이웃으로 볼지 정한 창","more":"창 크기 m 을 한쪽 개수로 적어요(논문마다 양쪽 합으로 적기도 해요). 창을 한 칸씩 밀며 반복해요."},{"ko":"스킵그램","en":"Skip-gram","say":"중심 단어로 주변 문맥 단어를 맞히는 word2vec 방식","more":"P(o|c) 를 크게 만들어요. 드문 단어와 작은 데이터에 조금 유리하다고 해요. gensim 에서 sg=1 이에요."},{"ko":"연속 단어 주머니","en":"CBOW","say":"주변 문맥 단어들로 중심 단어를 맞히는 word2vec 방식","more":"Continuous Bag of Words 예요. 스킵그램과 방향만 반대이고 기본 생각은 같아요. gensim 에서 sg=0 이에요."},{"ko":"자기 지도 학습","en":"Self-supervised Learning","say":"데이터가 스스로 문제와 정답을 만들어 주는 학습","more":"사람이 라벨을 달지 않아도 '가운데 단어의 이웃은 이 단어들' 이라는 정답이 글 안에 이미 있어요. GPT 의 다음 토큰 예측도 같은 철학이에요."},{"ko":"조건부 확률","en":"Conditional Probability","say":"어떤 것이 주어졌을 때 다른 것이 일어날 확률","more":"P(o|c) 는 'c 가 주어졌을 때 o 의 확률' 이라 읽어요(P o given c)."},{"ko":"목적 함수","en":"Objective Function","say":"학습이 가장 크게 또는 가장 작게 만들려는 목표 식","more":"word2vec 에서는 우도에 로그를 씌우고 부호를 뒤집고 T 로 나눈 J(θ) 를 가장 작게 만들어요."},{"ko":"손실 함수","en":"Loss Function","say":"틀린 정도를 숫자로 매기는 벌점 식","more":"word2vec 의 J(θ) 가 손실 함수예요. 학습은 이 벌점을 가장 줄이는 방향으로 파라미터를 고치는 일이에요."},{"ko":"음의 로그 우도","en":"Negative Log-Likelihood (NLL)","say":"확률에 로그를 씌우고 마이너스를 붙인 벌점","more":"정답 확률이 1에 가까우면 0에 가깝고, 0에 가까우면 아주 커져요. 딥러닝에서 가장 흔한 손실 함수예요."},{"ko":"소프트맥스","en":"Softmax","say":"아무 실수 점수들을 모두 더해 1이 되는 확률로 바꾸는 함수","more":"점수마다 exp 를 씌워 양수로 만들고, 전체 합으로 나눠요. 큰 점수는 두드러지고(max), 작은 점수도 0이 되지 않아요(soft)."},{"ko":"파라미터","en":"Parameter","say":"학습하면서 고쳐 나가는 모델 속 숫자들","more":"word2vec 에서는 모든 단어의 u 벡터와 v 벡터가 전부예요. 합쳐서 θ 라 부르고 2 × d × V 개예요."},{"ko":"경사 하강법","en":"Gradient Descent","say":"기울기 반대 방향으로 조금씩 걸어 손실을 줄이는 방법","more":"θ_new = θ_old - α∇J 한 줄이에요. 모든 신경망 학습, GPT 학습도 이 원리예요."},{"ko":"확률적 경사 하강법","en":"Stochastic Gradient Descent (SGD)","say":"전체 데이터 대신 몇 개 창(미니배치)만 보고 기울기를 어림해 자주 걷는 방법","more":"정확하지만 느린 것보다 흔들려도 빠른 것이 낫다는 딥러닝의 기본값이에요."},{"ko":"학습률","en":"Learning Rate","say":"경사 하강법에서 한 번에 걷는 보폭 α","more":"너무 크면 튕겨 나가 발산하고, 너무 작으면 끝없이 오래 걸려요."},{"ko":"기울기","en":"Gradient","say":"각 파라미터를 조금 바꿀 때 손실이 얼마나 변하는지 모은 벡터","more":"∇J 로 적고 '어느 쪽이 오르막인가' 를 알려 줘요. 반대로 가면 내리막이에요."},{"ko":"편미분","en":"Partial Derivative","say":"여러 변수 중 하나만 조금 바꿨을 때의 변화율","more":"기울기 ∇J 는 파라미터 하나하나에 대한 편미분을 모은 벡터예요."},{"ko":"미니배치","en":"Mini-batch","say":"전체 데이터에서 몇 개만 뽑은 작은 묶음","more":"SGD 는 미니배치로 기울기를 어림하고 한 걸음 걸어요. 한 바퀴 동안 걸음을 아주 많이 걸을 수 있어요."},{"ko":"연쇄 법칙","en":"Chain Rule","say":"겹쳐진 함수를 미분할 때 안쪽, 바깥쪽 미분을 곱해 이어 가는 규칙","more":"맞물린 톱니바퀴처럼 변화가 전해져요. log P(o|c) 를 v_c 로 미분할 때 몇 줄 쓰면 돼요."},{"ko":"네거티브 샘플링","en":"Negative Sampling","say":"진짜 이웃 단어 하나와 아무렇게나 뽑은 가짜 단어 몇 개만 비교해서 빠르게 배우는 방법","more":"소프트맥스처럼 어휘 전체(10만 개)와 내적하지 않고, 진짜 짝 1개와 가짜 k개를 가려내는 이진 분류로 바꿔요. 가짜는 빈도의 3/4 제곱 비율로 뽑아요."},{"ko":"시그모이드","en":"Sigmoid","say":"아무 숫자나 넣으면 0과 1 사이 값으로 바꿔 주는 S자 함수","more":"식은 1/(1+exp(-x)) 이고, 0을 넣으면 0.5, 2를 넣으면 약 0.88, -2를 넣으면 약 0.12가 나와요. '예일 확률' 하나를 낼 때 써요."},{"ko":"이진 분류","en":"Binary Classification","say":"예, 아니오 둘 중 하나를 고르는 문제","more":"네거티브 샘플링은 '이 짝이 진짜 이웃인가?'를 예, 아니오로 가리는 이진 분류로 바꿔요. 시그모이드가 '예일 확률'을 내요."},{"ko":"단어 유추","en":"Word Analogy","say":"a 대 b 는 c 대 무엇? 을 벡터 셈으로 푸는 시험","more":"man : woman :: king : ? 이면 b - a + c 와 코사인 유사도가 가장 큰 단어를 골라요. 구글 유추 데이터는 19,544 문항이에요."},{"ko":"동시 발생 행렬","en":"Co-occurrence Matrix","say":"어떤 단어가 어떤 단어 옆에 몇 번 함께 나왔는지 센 표","more":"행이 대상 단어, 열이 문맥 단어예요. 어휘가 10만이면 10만 x 10만 표가 되고 대부분 0이에요."},{"ko":"글로브","en":"GloVe","say":"전체 말뭉치를 센 통계와 예측 학습을 합친 단어 벡터 방법","more":"Global Vectors 의 줄임말(2014)이에요. 두 단어 벡터의 내적이 함께 나온 횟수의 로그를 맞히도록 배워요. 수식은 시험에 내지 않는다고 했어요."},{"ko":"내적 평가","en":"Intrinsic Evaluation","say":"단어 벡터 자체를 바로 시험해 보는 평가","more":"단어 유추, 단어 유사도로 재요. 빠르고 어디가 문제인지 알려 주지만, 실제 성능과 이어지는지는 따로 보여야 해요."},{"ko":"외적 평가","en":"Extrinsic Evaluation","say":"단어 벡터를 실제 과제에 끼워 넣어 최종 성능을 재는 평가","more":"개체명 인식, 분류, 검색 같은 과제로 재요. 진짜 중요한 값이지만 느리고, 어디가 문제인지는 못 알려 줘요."},{"ko":"특이값 분해","en":"Singular Value Decomposition (SVD)","say":"큰 표를 세 행렬의 곱으로 쪼개서 중요한 방향 몇 개만 남기는 방법","more":"X ≈ U_k Σ_k V_k^T 처럼 위쪽 k 개 특이값만 남겨, 듬성듬성한 큰 벡터를 촘촘한 작은 벡터로 줄여요."},{"ko":"잠재 의미 분석","en":"Latent Semantic Analysis (LSA)","say":"단어-문서 표를 SVD 로 줄여 숨은 뜻 구조를 찾는 옛 방법","more":"세기로 벡터를 얻는 고전적인 길이에요. SVD 로 k 차원만 남겨요."},{"ko":"기능어","en":"Function Word","say":"the, of 처럼 문법 역할만 하고 뜻은 적은 단어","more":"거의 모든 문장에 나와서 그냥 세면 표를 온통 지배해요. 그래서 빼거나 줄이는 보정을 해요."},{"ko":"가중치 함수","en":"Weighting Function","say":"GloVe 에서 단어 짝 하나를 얼마나 믿을지 정하는 무게","more":"f(x) = (x/x_max)^α (x < x_max), 그 이상은 1. x_max = 100, α = 3/4 예요. 너무 흔한 짝이 지배하지 않게 막아요."},{"ko":"단어 유사도","en":"Word Similarity","say":"사람이 매긴 두 단어의 비슷함 점수와 벡터의 코사인이 얼마나 같이 가는지 보는 시험","more":"WordSim-353 은 353 쌍이에요. 예 tiger-cat 7.35, tiger-tiger 10, stock-jaguar 0.92."},{"ko":"개체명 인식","en":"Named Entity Recognition (NER)","say":"글에서 사람, 장소, 기관 같은 이름을 찾아 표시하는 과제","more":"외적 평가에 쓰는 실제 과제의 예예요."},{"ko":"분류","en":"Classification","say":"글을 정해진 칸(긍정/부정 등) 중 하나로 나누는 과제","more":"외적 평가에서 단어 벡터를 넣어 성능을 재는 과제의 예예요."},{"ko":"다의어","en":"Polysemy","say":"한 단어가 여러 뜻을 가진 것","more":"'배'는 먹는 배, 타는 배, 몸의 배예요. 단어 하나에 벡터 하나라서 세 뜻이 뭉개진 평균이 돼요."},{"ko":"편향","en":"Bias","say":"말뭉치에 스며 있는 사회적 치우침을 벡터가 그대로 배우는 것","more":"man : programmer :: woman : homemaker 가 실제 2016년 논문 제목이에요. 찾고 줄이는 연구는 있지만 뿌리는 아직 못 풀었어요."},{"ko":"정적 단어 벡터","en":"Static Word Vector","say":"한 번 학습이 끝나면 문맥이 바뀌어도 그대로인 단어 벡터","more":"word2vec, GloVe 벡터가 여기에 들어가요. 그래서 다의어를 구별하지 못해요."},{"ko":"문맥 임베딩","en":"Contextual Embedding","say":"같은 단어라도 문맥에 따라 벡터가 달라지는 임베딩","more":"다의어 문제의 해결책이에요. 5주차 BERT 에서 배워요."},{"ko":"편향","en":"Bias (사회적 편향. 신경망의 bias 항은 \"편향 항(bias term)\")","say":"말뭉치에 스며든 사회의 치우침을 벡터가 그대로 배우는 것이에요."}],"2L":[{"ko":"코랩","en":"Colab","say":"구글이 주는, 브라우저에서 파이썬 노트북을 돌리는 무료 컴퓨터예요.","more":"설치 없이 셀 단위로 코드를 실행하고, 런타임 유형에서 GPU 를 켤 수 있어요. 이 수업 실습은 모두 Colab 에서 해요."},{"ko":"그래픽 처리 장치","en":"GPU","say":"행렬 계산을 한꺼번에 아주 많이 하는 계산 장치예요.","more":"신경망 학습은 행렬 곱의 반복이라 GPU 가 CPU 보다 훨씬 빨라요. Colab 에서는 T4 GPU 를 빌려 써요."},{"ko":"쿠다","en":"CUDA","say":"PyTorch 가 NVIDIA GPU 를 쓰게 해 주는 소프트웨어 이름이에요.","more":"torch.cuda.is_available() 가 True 면 GPU 를 쓸 수 있다는 뜻이에요. 코드에서 device 를 \"cuda\" 로 정해요."},{"ko":"텐서","en":"Tensor","say":"PyTorch 가 쓰는 숫자 배열(벡터, 행렬, 그 이상)이에요.","more":"torch.randn(3, 3) 은 3행 3열 텐서예요. .shape 로 모양을, .device 로 CPU 에 있는지 GPU 에 있는지 봐요."},{"ko":"파이토치","en":"PyTorch","say":"신경망을 만들고 학습시키는 파이썬 도구 모음이에요.","more":"텐서 계산, 자동 미분, 신경망 층을 제공해요. import torch 로 불러와요."},{"ko":"허깅페이스","en":"Hugging Face","say":"미리 학습된 NLP 모델과 토크나이저를 모아 둔 '앱 스토어' 같은 곳이에요.","more":"transformers 라이브러리로 모델 이름만 적으면 내려받아 쓸 수 있어요. 노트북은 이것을 'NLP 의 앱 스토어' 라고 불러요."},{"ko":"파이프라인","en":"pipeline","say":"허깅페이스에서 모델, 토크나이저, 전처리를 한 줄로 묶어 바로 쓰게 해 주는 함수예요.","more":"pipeline(\"sentiment-analysis\") 처럼 할 일 이름만 주면 알맞은 모델을 받아 결과를 돌려줘요."},{"ko":"토크나이저","en":"Tokenizer","say":"글을 토큰으로 자르고 번호로 바꿔 주는 도구예요.","more":"모델마다 자기 토크나이저가 있어요. 같은 문장도 토크나이저에 따라 토큰 수가 크게 달라져요."},{"ko":"토큰","en":"Token","say":"모델이 읽는 글의 한 조각이에요. 레고 조각이라고 생각해요.","more":"단어일 수도, 글자일 수도, 단어의 일부(서브워드)일 수도 있어요."},{"ko":"바이트 쌍 인코딩","en":"Byte Pair Encoding (BPE)","say":"가장 자주 붙어 나오는 두 조각을 한 조각으로 합치기를 반복해 어휘를 만드는 방법이에요.","more":"글자에서 시작해 쌍 세기, 가장 많은 쌍 합치기, 규칙 기록을 정해진 횟수만큼 반복해요(N2 p.11)."},{"ko":"병합 규칙","en":"Merge Rule","say":"BPE 가 배운 '이 두 조각은 붙여라' 라는 규칙이에요.","more":"학습한 순서대로 기록해 두었다가, 새 단어를 자를 때 같은 순서로 다시 적용해요."},{"ko":"말뭉치","en":"Corpus","say":"모델을 학습시키려고 모아 둔 글 전체예요.","more":"실습의 장난감 말뭉치는 low, lower, newest, widest 네 단어와 횟수, 진짜 말뭉치는 NSMC 영화 리뷰 15만 개예요."},{"ko":"어휘","en":"Vocabulary","say":"모델이 아는 토큰 종류의 목록이에요. 레고 상자에 든 조각 종류 목록이에요.","more":"vocab_size=8000 이면 토큰 종류를 8000 개까지 만들어요."},{"ko":"토큰 과다 분할","en":"Fertility","say":"단어 하나가 평균 몇 개의 토큰으로 쪼개지는지예요.","more":"토큰 수 ÷ 공백 단어 수. 영어 중심 토크나이저는 한국어를 잘게 쪼개서 fertility 가 커지고, 그만큼 비용과 문맥 자리를 더 써요(N2 p.20)."},{"ko":"네이버 영화 리뷰 말뭉치","en":"NSMC","say":"네이버 영화 리뷰 15만 개에 긍정, 부정 표시가 붙은 한국어 데이터예요.","more":"Naver Sentiment Movie Corpus. 실습에서 한국어 토크나이저와 word2vec 을 학습시키는 재료로 써요."},{"ko":"워드투벡","en":"word2vec","say":"주변에 오는 단어를 맞히게 학습해서 단어마다 벡터를 얻는 방법이에요.","more":"'친구를 보면 그 사람을 안다' 는 분포 가설을 학습으로 옮긴 것. 2013년에 나왔어요(N2 p.28)."},{"ko":"스킵그램","en":"Skip-gram","say":"중심 단어로 주변 문맥 단어를 맞히는 word2vec 방식이에요.","more":"gensim 에서 sg=1 이면 Skip-gram, sg=0 이면 CBOW 예요. 강의가 기본으로 쓰는 방식이에요(N2 p.40)."},{"ko":"네거티브 샘플링","en":"Negative Sampling","say":"진짜 문맥 단어 하나와 가짜 단어 몇 개만 구별하게 해서 계산을 줄이는 방법이에요.","more":"어휘 전체에 소프트맥스를 하지 않아도 돼요. negative=10 은 가짜 단어를 10개 뽑는다는 뜻이에요(N2 p.38-39)."},{"ko":"윈도우","en":"Window","say":"중심 단어 앞뒤로 문맥으로 볼 칸 수예요.","more":"window=5 면 앞뒤 5칸 안의 단어를 문맥 단어로 봐요. 강의 식의 m 이에요."},{"ko":"임베딩","en":"Embedding","say":"토큰을 숫자 벡터로 바꾼 것, 곧 단어의 지도 좌표예요.","more":"vector_size=100 이면 단어마다 숫자 100개짜리 벡터가 생겨요. 뜻이 비슷하면 가까이 있어요."},{"ko":"코사인 유사도","en":"Cosine Similarity","say":"두 벡터가 얼마나 같은 쪽을 보는지 -1 에서 1 사이 숫자로 잰 값이에요.","more":"내적을 두 벡터 길이의 곱으로 나눠요. most_similar 와 similarity 가 이 값을 써요."},{"ko":"단어 유추","en":"Word Analogy","say":"'왕 - 남자 + 여자 = ?' 처럼 벡터 더하기 빼기로 관계를 맞히는 문제예요.","more":"단어 벡터를 내적 평가하는 대표 방법이에요(N2 p.48). 작은 말뭉치에서는 결과가 잘 안 나올 수 있어요."},{"ko":"미등록 단어","en":"Out-of-Vocabulary (OOV)","say":"어휘에 없어서 모델이 모르는 단어예요.","more":"word2vec 은 min_count 보다 적게 나온 단어를 어휘에 넣지 않아서, 그런 단어는 벡터가 없어요."},{"ko":"주성분 분석","en":"PCA","say":"많은 칸짜리 벡터를 정보를 최대한 남기며 2칸으로 줄여 그림으로 그리는 방법이에요.","more":"100차원 단어 벡터를 2차원 점으로 바꿔서 비슷한 단어가 모이는지 눈으로 봐요."},{"ko":"언어 모델","en":"Language Model (LM)","say":"앞 글을 보고 다음 토큰을 맞히는 모델이에요. 휴대폰 자판의 다음 단어 추천 같은 거예요.","more":"KoGPT-2 가 '자연어 처리는' 뒤를 이어 쓰는 것이 언어 모델이에요. 3주차에서 자세히 배워요."}],"3":[{"ko":"자연어처리","en":"Natural Language Processing (NLP)","say":"컴퓨터가 사람의 말과 글을 다루게 하는 분야","more":"글을 토큰으로 자르고, 벡터로 바꾸고, 그 벡터로 뜻을 맞히거나 다음 말을 만들어요."},{"ko":"토큰","en":"Token","say":"글을 자른 레고 조각 하나","more":"모델이 읽는 가장 작은 단위예요. 단어일 수도, 단어의 조각(서브워드)일 수도 있어요."},{"ko":"바이트 쌍 인코딩","en":"Byte Pair Encoding (BPE)","say":"자주 붙어 다니는 두 조각을 한 조각으로 접착하는 토큰화 방법","more":"2주차에 배운 서브워드 토큰화예요. 가장 자주 나오는 쌍을 계속 합쳐 어휘를 만들어요."},{"ko":"워드투벡","en":"word2vec","say":"주변 단어를 맞히면서 단어의 지도 좌표를 배우는 방법","more":"2주차의 핵심이에요. 친구(주변 단어)를 보면 그 단어를 안다는 생각으로 단어 벡터를 학습해요."},{"ko":"단어 벡터","en":"Word Vector","say":"단어의 지도 좌표. 뜻이 비슷하면 가까이 살아요","more":"숫자 여러 개를 줄 세운 것이에요. 3주차에는 이 벡터가 신경망의 입력이 돼요."},{"ko":"신경망","en":"Neural Network","say":"뉴런을 여러 층 쌓아 벡터를 받아 답을 내는 계산 기계","more":"가중합, 편향 항, 활성화 함수를 층마다 반복해요. 가중치와 편향은 학습으로 정해져요."},{"ko":"언어 모델","en":"Language Model (LM)","say":"휴대폰 자판의 다음 단어 추천처럼 다음 토큰을 맞히는 모델","more":"3주차 뒷부분(Part 3, 4)에서 자세히 배워요. GPT 같은 모델도 결국 언어 모델이에요."},{"ko":"개체명 인식","en":"Named Entity Recognition (NER)","say":"글 속에서 사람, 기관, 장소 같은 이름을 찾아 종류를 붙이는 일","more":"3주차에서 신경망을 설명할 때 계속 쓰는 예제 과제예요. 'Busan' 은 장소(LOCATION)라고 붙여요."},{"ko":"분류","en":"Classification","say":"입력을 보고 정해진 여러 칸 중 어느 칸인지 고르는 일","more":"칸 하나하나를 클래스라고 불러요. NER 은 단어마다 사람, 장소 같은 클래스를 고르는 분류예요."},{"ko":"윈도우","en":"Window","say":"가운데 단어 양옆으로 몇 단어씩 함께 보는 창","more":"m=2 이면 가운데 단어 앞 2개, 뒤 2개를 봐서 모두 5단어예요. 2주차 word2vec 에서도 나왔어요."},{"ko":"중심 단어","en":"Center Word","say":"윈도우 한가운데에 있어 지금 판단하려는 단어","more":"NER 창 분류에서는 이 단어가 장소인지를 묻고, 양옆 단어는 힌트로 써요."},{"ko":"지도 학습","en":"Supervised Learning","say":"문제와 정답을 짝으로 주고 배우게 하는 방법","more":"학습 자료가 (입력 x, 정답 y) 짝으로 되어 있어요. 모델은 정답을 맞히도록 가중치를 고쳐요."},{"ko":"레이블","en":"Label","say":"입력에 붙여 둔 정답 이름표","more":"'Busan' 에 LOCATION 을 붙여 두는 식이에요. 지도 학습의 y 가 레이블이에요."},{"ko":"소프트맥스","en":"Softmax","say":"점수를 모두 더해 1이 되는 확률 파이로 나누기","more":"각 점수에 exp 를 씌운 뒤 전체 합으로 나눠요. 결과는 0과 1 사이이고 다 더하면 1이에요."},{"ko":"교차 엔트로피","en":"Cross-Entropy","say":"정답 칸에 준 확률의 -log 를 벌점으로 매기는 손실","more":"정답 확률이 1에 가까우면 벌점이 0에 가깝고, 0에 가까우면 벌점이 크게 올라가요. 소프트맥스 + NLL 이에요."},{"ko":"손실 함수","en":"Loss Function","say":"틀린 정도를 매기는 벌점","more":"학습은 이 벌점이 작아지는 쪽으로 가중치를 조금씩 고치는 일이에요. 기호는 J(θ) 로 써요."},{"ko":"로짓","en":"Logit","say":"소프트맥스에 넣기 전의 날것 점수","more":"Wx 로 얻은 점수라서 음수도 양수도 될 수 있어요. 확률이 아니에요. 스코어(score)라고도 불러요."},{"ko":"선형 분류기","en":"Linear Classifier","say":"곧은 선(평면) 하나로만 두 무리를 가르는 분류기","more":"가중치 행렬 W 하나만 곱하는 모델이에요. 소프트맥스 분류기(로지스틱 회귀)도 선형 분류기예요."},{"ko":"결정 경계","en":"Decision Boundary","say":"분류기가 '여기부터는 A, 저기부터는 B' 라고 긋는 경계선","more":"선형 분류기의 결정 경계는 곧은 선이고, 비선형성이 있으면 휘어진 곡선이 될 수 있어요."},{"ko":"초평면","en":"Hyperplane","say":"n차원 공간을 둘로 가르는 n-1차원의 평평한 판","more":"2차원이면 선, 3차원이면 면이에요. 선형 분류기가 긋는 경계가 초평면이에요."},{"ko":"비선형성","en":"Nonlinearity","say":"곧은 선이 아니게 휘게 만드는 성질","more":"뉴런의 가중합 뒤에 활성화 함수를 거치게 해서 넣어요. 이게 없으면 층을 쌓아도 행렬 하나와 같아요."},{"ko":"뉴런","en":"Neuron","say":"가중합 + 편향 항을 계산하고 활성화 함수를 통과시키는 작은 계산 단위","more":"하나의 뉴런은 학습된 패턴 탐지기 하나예요. 식은 h = f(wᵀx + b) 예요."},{"ko":"가중치","en":"Weight","say":"입력마다 얼마나 중요하게 볼지 곱하는 숫자","more":"뉴런 여러 개의 가중치를 모으면 행렬 W 가 돼요. 학습으로 정해지는 파라미터예요."},{"ko":"편향 항","en":"Bias Term","say":"가중합에 더하는 숫자 하나 b","more":"입력이 모두 0이어도 뉴런이 켜지는 기준을 옮겨 줘요. 사회적 편향(Bias)과 다른 말이에요."},{"ko":"가중합","en":"Weighted Sum","say":"입력마다 가중치를 곱해서 모두 더한 값","more":"w₁x₁ + w₂x₂ + ... 이에요. 여기에 편향 항 b 를 더한 z = wᵀx + b 를 아핀 변환이라고도 불러요."},{"ko":"활성화 함수","en":"Activation Function","say":"가중합 결과 z 를 받아 휘어진 값 f(z) 로 바꾸는 함수","more":"시그모이드, tanh, ReLU, GELU 가 대표예요. 신경망에 비선형성을 넣는 부품이에요."},{"ko":"시그모이드","en":"Sigmoid","say":"어떤 수든 0과 1 사이로 눌러 주는 S자 함수","more":"f(z) = 1 / (1 + e^(-z)) 예요. 확률이나 LSTM 의 게이트처럼 0~1 값이 필요할 때 써요."},{"ko":"하이퍼볼릭 탄젠트","en":"tanh","say":"어떤 수든 -1과 1 사이로 눌러 주는 S자 함수","more":"시그모이드와 모양이 비슷하지만 가운데가 0이에요. 양 끝으로 가면 기울기가 거의 0이 돼요."},{"ko":"렐루","en":"ReLU","say":"음수는 0으로 끄고 양수는 그대로 통과시키는 함수","more":"f(z) = max(z, 0) 이에요. 싸고 빠르고 성능이 좋아서 딥러닝의 일꾼(workhorse)이라고 불러요."},{"ko":"겔루","en":"GELU","say":"ReLU 를 부드럽게 다듬은 활성화 함수","more":"0 근처에서 뚝 자르지 않고 부드럽게 변해요. 트랜스포머에서 주로 써요(4주차에 다시 나와요)."},{"ko":"다층 퍼셉트론","en":"Multi-Layer Perceptron (MLP)","say":"뉴런 층을 여러 겹 쌓은 가장 기본 신경망","more":"h(1) = f(W(1)x + b(1)), h(2) = f(W(2)h(1) + b(2)), ŷ = softmax(U h(2)) 처럼 같은 계산을 반복해요."},{"ko":"은닉층","en":"Hidden Layer","say":"입력과 출력 사이에 숨어 있는 중간 층","more":"밖에서는 입력과 출력만 보이고 가운데 계산은 안 보여서 '숨은(hidden)' 층이라고 불러요."},{"ko":"파라미터","en":"Parameter","say":"학습으로 정해지는 숫자들(가중치와 편향 항)","more":"처음에는 무작위로 시작하고, 손실 함수를 줄이는 쪽으로 조금씩 고쳐요. 모아서 θ 라고 써요."},{"ko":"합성곱 신경망","en":"Convolutional Neural Network (CNN)","say":"작은 필터를 미끄러뜨리며 부분 패턴을 찾는 신경망","more":"글에서는 단어 몇 개짜리 창을 훑어 n-gram 패턴을 찾아요. 모든 창을 한꺼번에(병렬로) 계산해서 빨라요."},{"ko":"합성곱 필터","en":"Convolution Filter","say":"문장을 따라 미끄러지며 작은 패턴을 찾는 숫자 판","more":"폭 3짜리 필터는 연속된 세 단어(trigram) 패턴 탐지기예요. 같은 필터를 문장 전체에 다시 써요."},{"ko":"특징 맵","en":"Feature Map","say":"필터가 창마다 낸 값을 줄 세운 결과","more":"창 하나마다 값 하나가 나와요. 값이 크면 그 자리에 필터가 찾는 패턴이 있다는 뜻이에요."},{"ko":"최대 풀링","en":"Max-pooling","say":"특징 맵에서 가장 큰 값 하나만 남기기","more":"'이 패턴이 문장 어디에서든 나왔나?' 를 묻는 것이라서, 어디서 나왔는지는 버려요."},{"ko":"엔그램","en":"n-gram","say":"바로 붙어 있는 단어 n개 묶음","more":"2개면 bigram, 3개면 trigram 이에요. 3주차 Part 3 에서 n-gram 언어 모델로 다시 나와요."},{"ko":"보편 근사 정리","en":"Universal Approximation Theorem","say":"은닉 뉴런이 충분하면 웬만한 함수는 다 흉내 낼 수 있다는 정리","more":"비선형 활성화 함수가 있을 때 성립해요. 그래서 비선형성이 있는 신경망이 강력해요."},{"ko":"역전파","en":"Backpropagation","say":"틀린 책임을 뒤에서 앞으로 나눠 주기","more":"손실 함수의 기울기를 출력 쪽에서 입력 쪽으로 연쇄 법칙으로 계산해요. 3주차 Part 2 의 주제예요."},{"ko":"순환 신경망","en":"Recurrent Neural Network (RNN)","say":"한 단어씩 읽으며 메모장(은닉 상태)에 요약을 고쳐 쓰는 사람","more":"기억을 가진 읽는 사람(a reader with memory)이에요. 3주차 Part 4 에서 배워요."},{"ko":"기울기","en":"Gradient","say":"손실이 가장 빨리 커지는 방향과 그 가파름","more":"학습은 기울기의 반대 방향으로 한 걸음씩 내려가요. 안개 낀 산의 발밑 기울기예요."},{"ko":"기울기 소실","en":"Vanishing Gradient","say":"귓속말 전달 게임에서 말이 점점 희미해지듯 기울기가 0으로 사라지는 문제","more":"시그모이드, tanh 는 양 끝에서 기울기가 거의 0이라 층이 깊어지면 앞쪽 층까지 기울기가 잘 안 가요."},{"ko":"트랜스포머","en":"Transformer","say":"어텐션으로 문장을 한꺼번에 보는 요즘 언어 모델의 기본 구조","more":"4주차에 배워요. 활성화 함수로 GELU 를 많이 써요."},{"ko":"행렬","en":"Matrix","say":"숫자를 가로세로 표 모양으로 늘어놓은 것","more":"shape 은 (행 수, 열 수)로 써요. (3,5) 행렬에 길이 5 벡터를 곱하면 길이 3 벡터가 나와요."},{"ko":"로지스틱 회귀","en":"Logistic Regression","say":"점수를 확률로 바꿔 분류하는 가장 단순한 선형 분류기","more":"클래스가 여러 개면 소프트맥스 회귀라고도 해요. 행렬 W 하나만 곱하므로 선형이에요."},{"ko":"순전파","en":"Forward Pass","say":"입력에서 출력 쪽으로 계산을 차례로 해 나가는 것","more":"계산 그래프를 왼쪽에서 오른쪽으로 방문하며 각 노드 값을 구하고, 역방향 패스에서 다시 쓰려고 그 값을 저장해 둬요."},{"ko":"경사 하강법","en":"Gradient Descent","say":"안개 낀 산에서 발밑 기울기만 보고 한 걸음씩 내려가기","more":"파라미터에서 학습률 × 기울기를 빼는 일을 반복해 손실을 줄여요."},{"ko":"확률적 경사 하강법","en":"Stochastic Gradient Descent (SGD)","say":"데이터 일부(작은 묶음)로 기울기를 구해 자주, 조금씩 내려가는 경사 하강법","more":"전체 데이터를 다 보지 않고 일부만 봐서 빠르게 여러 번 업데이트해요. word2vec도 이 방법으로 학습했어요."},{"ko":"학습률","en":"Learning Rate","say":"경사 하강법에서 한 걸음의 보폭","more":"식의 α(알파)예요. 너무 크면 골짜기를 건너뛰고, 너무 작으면 학습이 느려요."},{"ko":"행렬 미적분","en":"Matrix Calculus","say":"벡터와 행렬로 된 식을 미분하는 방법","more":"한 변수 미분의 '살짝 밀기' 생각을 벡터, 행렬로 넓힌 것이에요. 역전파 식을 손으로 유도할 때 써요."},{"ko":"미분","en":"Derivative","say":"입력을 살짝 밀면 출력이 얼마나 움직이는지, 즉 그래프의 기울기","more":"f(x) = x³ 이면 f'(x) = 3x² 이에요. x = 2 에서는 12라서, x를 조금 밀면 f는 그 12배쯤 움직여요."},{"ko":"야코비안","en":"Jacobian","say":"입력 여러 개, 출력 여러 개인 함수의 미분을 모아 놓은 표(행렬)","more":"출력이 m개, 입력이 n개면 m×n 행렬이고, (i, j) 칸은 j번째 입력을 살짝 바꿀 때 i번째 출력이 얼마나 변하는지예요."},{"ko":"편미분","en":"Partial Derivative","say":"입력이 여러 개일 때 하나만 살짝 바꾸고 나머지는 그대로 두고 구한 미분","more":"∂(라운드) 기호로 써요. 입력마다 편미분을 모으면 기울기 벡터가 돼요."},{"ko":"연쇄 법칙","en":"Chain Rule","say":"여러 단계를 거친 함수의 미분은 단계마다의 미분을 곱하면 된다는 규칙","more":"맞물린 톱니바퀴처럼, x가 z를 3배로 돌리고 z가 h를 8배로 돌리면 x는 h를 24배로 돌려요. 벡터에서는 야코비안 행렬을 곱해요."},{"ko":"국소 기울기","en":"Local Gradient","say":"노드 하나가 자기 입력과 출력만 보고 구한 미분","more":"∂y/∂x예요. 노드는 네트워크 전체를 몰라도 이것만 알면 돼요."},{"ko":"전치","en":"Transpose","say":"행렬의 행과 열을 뒤바꾸는 것, 위첨자 T로 표시","more":"(3×1) 세로 벡터를 전치하면 (1×3) 가로 벡터가 돼요. 역전파 식의 전치는 shape을 맞추려고 붙어요."},{"ko":"원소별 곱","en":"Hadamard Product","say":"같은 자리 원소끼리만 곱하는 곱, 기호 ⊙","more":"[2, 3] ⊙ [1, 0] = [2, 0]이에요. 대각 행렬을 곱한 것과 결과가 같아요."},{"ko":"대각 행렬","en":"Diagonal Matrix","say":"대각선 칸에만 숫자가 있고 나머지는 모두 0인 정사각 행렬","more":"활성화 함수의 야코비안이 이렇게 생겼어요. hᵢ는 zᵢ에만 영향을 받기 때문이에요."},{"ko":"단위 행렬","en":"Identity Matrix","say":"대각선이 모두 1이고 나머지는 0인 행렬, 곱해도 아무것도 안 바뀌어요","more":"숫자 1과 같은 역할이에요. Wx + b를 b로 미분하면 단위 행렬 I가 나와요."},{"ko":"임베딩","en":"Embedding","say":"토큰을 벡터로 바꾼 것, 또는 그 벡터들의 표","more":"단어 벡터와 거의 같은 뜻으로 써요. 학습 중에 같이 고칠 수도, 그대로 얼려 둘 수도 있어요."},{"ko":"외적","en":"Outer Product","say":"세로 벡터 × 가로 벡터로 표(행렬)를 만드는 곱","more":"(3×1)(1×5) = (3×5)처럼 모든 짝을 곱해 칸을 채워요. ∂s/∂W = δᵀxᵀ가 외적이에요."},{"ko":"오차 신호","en":"Error Signal","say":"출력 쪽에서 거꾸로 흘러와 한 층에 도착한 기울기, 기호 δ(델타)","more":"3강 예에서는 δ = ∂s/∂z 예요. 한 번 구해 b, W, x의 기울기에 모두 다시 써요."},{"ko":"상류 기울기","en":"Upstream Gradient","say":"내 출력 쪽(뒤)에서 나에게 내려온 기울기","more":"노드 입장에서 ∂J/∂y예요. 여기에 내 국소 기울기를 곱해 앞으로 넘겨요."},{"ko":"텐서","en":"Tensor","say":"숫자를 여러 방향으로 쌓은 묶음(숫자 하나, 벡터, 행렬, 그 이상)","more":"PyTorch가 다루는 기본 자료예요. tensor.shape로 크기를 볼 수 있어요."},{"ko":"모양","en":"Shape","say":"벡터나 행렬이 몇 행 몇 열인지 적은 크기 정보","more":"(3, 5)는 3행 5열이에요. 역전파 식이 맞는지 가장 빨리 확인하는 방법이 shape 맞추기예요."},{"ko":"계산 그래프","en":"Computation Graph","say":"계산을 노드(입력값, 연산)와 선(값의 흐름)으로 그린 그림","more":"입력은 시작 노드, 더하기나 곱하기 같은 연산은 중간 노드예요. PyTorch는 순전파를 할 때마다 이 그래프를 자동으로 만들어요."},{"ko":"노드","en":"Node","say":"계산 그래프의 동그라미 하나, 입력값이거나 연산 하나","more":"각 노드는 자기 국소 기울기만 알면 되고, 네트워크 전체를 볼 필요가 없어요."},{"ko":"역방향 패스","en":"Backward Pass","say":"출력에서 입력 쪽으로 거꾸로 가며 기울기를 구하는 단계","more":"출력의 기울기 1에서 출발해, 노드마다 상류 기울기 × 국소 기울기를 곱해 앞쪽으로 넘겨요."},{"ko":"하류 기울기","en":"Downstream Gradient","say":"내가 계산해서 내 입력 쪽(앞)으로 넘겨주는 기울기","more":"하류 기울기 = 상류 기울기 × 국소 기울기예요."},{"ko":"위상 순서","en":"Topological Order","say":"계산 그래프에서 필요한 값이 먼저 나오도록 정한 방문 순서","more":"순전파는 이 순서대로, 역방향 패스는 이 순서를 거꾸로 방문해요."},{"ko":"자동 미분","en":"Automatic Differentiation (Autodiff)","say":"프로그램이 계산 그래프를 따라 미분을 자동으로 해 주는 기능","more":"연산마다 자기 국소 기울기를 알고 있어서 역전파를 대신 실행해 줘요. PyTorch의 오토그래드가 그 예예요."},{"ko":"기울기 검사","en":"Gradient Checking","say":"손으로 구한 기울기가 맞는지, 값을 살짝 흔들어 얻은 숫자와 비교해 확인하는 방법","more":"f(θ+h)와 f(θ-h)의 차이를 2h로 나눈 수치 기울기와 비교해요. 느리지만 틀리기가 거의 어려워서 디버깅용으로 써요."},{"ko":"수치 기울기","en":"Numeric Gradient","say":"값을 아주 조금 올리고 내려서 생긴 차이로 어림한 기울기","more":"(f(θ+h) - f(θ-h)) / 2h 이고 h는 0.0001쯤이에요. 파라미터마다 따로 계산해야 해서 느려요."},{"ko":"오토그래드","en":"autograd","say":"PyTorch 안의 자동 미분 장치","more":"loss.backward() 한 줄이면 계산 그래프를 거꾸로 걸으며 모든 파라미터의 .grad 를 채워요."},{"ko":"기울기 폭발","en":"Exploding Gradient","say":"기울기가 층을 지날수록 점점 커져 학습이 튀는 문제","more":"기울기 소실의 반대예요. 뒤에서 기울기 클리핑으로 막는 법을 배워요."},{"ko":"다음 토큰 예측","en":"Next Token Prediction","say":"지금까지 나온 토큰으로 바로 다음 토큰을 맞히는 과제","more":"교수님은 GPT도 결국 이것이고, 이것이 거의 모든 걸 결정한다고 했어요."},{"ko":"퍼플렉서티","en":"Perplexity (PPL)","say":"다음 단어를 고를 때 헷갈리는 후보가 평균 몇 개인지","more":"PPL = exp(교차 엔트로피 손실)이에요. 낮을수록 좋고, 최저는 1, 모든 단어에 똑같은 확률이면 어휘 크기 V 가 돼요."},{"ko":"확률 분포","en":"Probability Distribution","say":"가능한 후보마다 확률을 붙여 둔 목록. 모두 더하면 1","more":"언어 모델이 내는 다음 단어 확률 분포는 후보가 어휘 크기만큼 있어요. 예 {9pm: 0.2, noon: 0.1, midnight: 0.05, ...}."},{"ko":"조건부 확률","en":"Conditional Probability","say":"무엇이 이미 주어졌을 때 다른 일이 일어날 확률","more":"P(A | B) 는 'B 가 주어졌을 때 A 의 확률'이라고 읽어요. 언어 모델은 앞 단어들이 주어졌을 때 다음 단어의 조건부 확률을 내요."},{"ko":"확률의 연쇄 법칙","en":"Chain Rule of Probability","say":"글 전체의 확률을 '한 단어씩 다음 단어 확률'의 곱으로 쪼개는 규칙","more":"P(x1, ..., xT) = P(x1) x P(x2|x1) x P(x3|x1,x2) x ... 이에요. 미분의 연쇄 법칙(Chain Rule)과는 다른 규칙이에요."},{"ko":"어휘","en":"Vocabulary","say":"레고 상자에 든 조각 종류 목록, 곧 모델이 아는 토큰 목록","more":"다음 단어 후보의 수가 곧 어휘 크기예요. 모든 후보에 똑같이 확률을 주면 퍼플렉서티가 어휘 크기와 같아져요."},{"ko":"대규모 언어 모델","en":"Large Language Model (LLM)","say":"아주 큰 언어 모델. ChatGPT 같은 것","more":"Large Language Model 의 줄임말이에요. 가운데 두 글자 LM 이 바로 오늘 배우는 언어 모델이에요. 여전히 다음 토큰 예측으로 학습해요."},{"ko":"말뭉치","en":"Corpus","say":"학습에 쓰는 글을 잔뜩 모아 둔 것","more":"n-gram 은 말뭉치에서 단어 묶음이 몇 번 나왔는지 세어 확률을 구해요. 말뭉치에 없는 묶음은 0번이에요."},{"ko":"샘플링","en":"Sampling","say":"확률 분포에 따라 제비뽑기처럼 후보 하나를 뽑는 것","more":"확률이 큰 후보가 더 자주 뽑히지만 늘 1등만 뽑히지는 않아요. 뽑고, 붙이고, 반복하면 언어 모델이 글을 써요."},{"ko":"마르코프 가정","en":"Markov Assumption","say":"다음 단어는 바로 앞 n-1 개 단어에만 달려 있다고 치는 가정","more":"그보다 앞의 단어는 아무리 중요해도 버려요. n-gram 언어 모델이 세기만으로 확률을 구할 수 있게 해 주지만, 먼 문맥을 잃어요."},{"ko":"희소성 문제","en":"Sparsity Problem","say":"세어 보려는 단어 묶음이 말뭉치에 거의 안 나와서 횟수가 0 투성이인 문제","more":"분자가 0이면 확률이 0이 되고, 분모가 0이면 아예 나눌 수가 없어요. n 이 커질수록 심해져서 실제로는 n ≤ 5 를 써요."},{"ko":"스무딩","en":"Smoothing","say":"한 번도 못 본 묶음에도 아주 작은 확률을 나눠 주는 보정","more":"분자가 0이라서 확률이 0이 되는 문제를 고치는 방법이에요(슬라이드: fix: smoothing)."},{"ko":"백오프","en":"Back-off","say":"긴 문맥으로 못 세면 더 짧은 문맥으로 물러나 세는 방법","more":"분모(앞 문맥)가 말뭉치에 한 번도 없을 때 쓰는 고치기예요. 예 4-gram 이 안 되면 3-gram 으로요."},{"ko":"원-핫 벡터","en":"One-hot Vector","say":"단어마다 자기 자리만 1이고 나머지는 모두 0인 벡터","more":"두 단어 벡터의 내적이 늘 0이라 비슷함을 전혀 나타내지 못해요. n-gram 의 '유사도 없음'도 같은 병이에요."},{"ko":"샘플링 온도","en":"Temperature","say":"샘플링을 얼마나 과감하게 할지 정하는 손잡이","more":"점수를 온도로 나눈 뒤 소프트맥스를 해요. 낮으면(0.5) 무난한 1등 위주, 높으면(1.5) 엉뚱한 후보도 자주 뽑혀요."},{"ko":"기하 평균","en":"Geometric Mean","say":"곱해서 개수만큼 제곱근을 씌운 평균","more":"숫자 T 개를 모두 곱한 뒤 1/T 제곱을 해요. 퍼플렉서티는 '정답 확률의 역수'의 기하 평균이에요."},{"ko":"토크나이저","en":"Tokenizer","say":"글을 토큰으로 잘라 주는 도구","more":"퍼플렉서티는 같은 토크나이저를 쓴 모델끼리만 비교할 수 있어요. 실습 N3L p.18~26 에서 직접 확인해요."},{"ko":"고정 윈도우 신경망 언어 모델","en":"Fixed-window Neural LM","say":"앞의 정해진 몇 단어만 임베딩으로 바꿔 신경망에 넣고 다음 단어를 맞히는 모델","more":"n-gram 과 달리 임베딩 덕분에 비슷한 단어끼리 정보를 나눠요. 하지만 창(윈도우) 크기가 여전히 고정이에요. 4부 첫 쪽(p.44)에서 봐요."},{"ko":"은닉 상태","en":"Hidden State","say":"RNN 이 지금까지 읽은 내용을 적어 두는 메모장","more":"h(t) 로 써요. 새 단어를 읽을 때마다 이전 메모 h(t-1)와 새 단어를 섞어 고쳐 써요."},{"ko":"시간 역전파","en":"Backpropagation Through Time (BPTT)","say":"RNN 을 시간 축으로 쫙 펼친 다음 보통 역전파를 하는 것","more":"같은 W_h 가 시점마다 쓰이므로 그 자리들의 기울기를 모두 더해요. 새 미분법이 아니에요."},{"ko":"기울기 클리핑","en":"Gradient Clipping","say":"기울기가 너무 길면 방향은 두고 길이만 잘라 주기","more":"기울기 폭발은 막아 주지만 기울기 소실은 못 고쳐요."},{"ko":"장단기 메모리","en":"LSTM","say":"장기 기억용 고속도로와 게이트를 더한 RNN","more":"기울기가 고속도로를 타고 흘러서 먼 거리 의존을 배우기 훨씬 쉬워져요."},{"ko":"게이트","en":"Gate","say":"무엇을 기억하고 무엇을 지울지 모델이 스스로 정하는 문","more":"잊기, 쓰기, 내보내기 세 가지 문이 있어요."},{"ko":"어텐션","en":"Attention","say":"필요한 곳을 골라 보는 장치","more":"과거를 벡터 하나에 욱여넣지 말고, 필요할 때 어느 자리를 볼지 고르자는 생각이에요. 4주차의 주인공이에요."},{"ko":"시퀀스-투-시퀀스","en":"seq2seq","say":"줄줄이 들어와 줄줄이 나가는 구조","more":"인코더 RNN 이 원문을 읽고 디코더 RNN 이 답 문장을 만들어요. 4주차의 출발점이에요."},{"ko":"인코더","en":"Encoder","say":"입력 문장을 끝까지 읽어 요약을 만드는 쪽","more":"seq2seq 에서 원문을 읽는 RNN 이에요."},{"ko":"디코더","en":"Decoder","say":"요약을 받아 답 문장을 한 토큰씩 만들어 내는 쪽","more":"디코더는 사실 조건이 붙은 언어 모델이에요."},{"ko":"기계 번역","en":"Machine Translation (MT)","say":"한 언어 문장을 다른 언어 문장으로 바꾸는 과제","more":"seq2seq 가 처음 크게 성공한 과제예요."},{"ko":"교사 강요","en":"Teacher Forcing","say":"학습할 때 정답 앞부분을 조건으로 넣어 주기","more":"매 시점마다 진짜 다음 단어를 알려 주고 그 단어에 대한 벌점을 계산해요."},{"ko":"병렬화","en":"Parallelization","say":"여러 계산을 한꺼번에 동시에 하기","more":"RNN 은 앞 시점을 기다려야 해서 병렬화가 안 돼요. 교수님이 시퀀셜은 컴퓨터 공학에서 아주 나쁜 단어라고 했어요."},{"ko":"스킵그램","en":"Skip-gram","say":"중심 단어로 주변 단어를 맞히는 word2vec 방식","more":"과제 2 에서 직접 구현해요."}],"3L":[{"ko":"텐서","en":"Tensor","say":"PyTorch 가 쓰는 숫자 배열(벡터, 행렬, 그 이상)이에요.","more":"torch.randn(3, 5) 는 3행 5열 텐서예요. .shape 로 모양을 봐요."},{"ko":"모양","en":"Shape","say":"텐서가 몇 줄 몇 칸인지 적은 튜플이에요. (3, 5) 처럼 써요.","more":"노트북 말: 딥러닝에서 가장 쓸모 있는 디버깅 습관은 shape 를 찍어 보는 것. 강의 N3 p.25-26 의 shape 맞추기와 같은 이야기예요."},{"ko":"자동 미분","en":"Automatic Differentiation (Autodiff)","say":"PyTorch 가 계산 그래프를 거꾸로 따라가며 기울기를 자동으로 구해 주는 기능이에요.","more":"PyTorch 에서는 autograd 라고 불러요. requires_grad=True 인 텐서로 계산한 뒤 .backward() 를 부르면 .grad 에 기울기가 채워져요(N3 p.32)."},{"ko":"기울기","en":"Gradient","say":"값을 조금 바꾸면 결과가 얼마나, 어느 쪽으로 바뀌는지 알려 주는 숫자(묶음)예요.","more":"손실을 줄이려면 기울기의 반대쪽으로 파라미터를 움직여요(경사 하강법)."},{"ko":"역전파","en":"Backpropagation","say":"틀린 책임을 출력에서 입력 쪽으로 거꾸로 나눠 주며 기울기를 구하는 방법이에요.","more":"연쇄 법칙을 계산 그래프 위에서 반복하는 것. loss.backward() 가 바로 이것이에요."},{"ko":"연쇄 법칙","en":"Chain Rule","say":"맞물린 톱니바퀴처럼, 여러 단계 함수의 미분은 단계별 미분을 곱해서 구해요.","more":"δ = u ⊙ tanh'(z) 도 s 를 h 로, h 를 z 로 미분한 것을 곱한 결과예요."},{"ko":"순환 신경망","en":"Recurrent Neural Network (RNN)","say":"한 글자(토큰)씩 읽으며 메모장(은닉 상태)에 요약을 고쳐 쓰는 신경망이에요.","more":"모든 시점에서 같은 가중치를 다시 써요. 그래서 문장이 길어져도 파라미터 수가 늘지 않아요(N3 p.46-47)."},{"ko":"은닉 상태","en":"Hidden State","say":"RNN 이 지금까지 읽은 내용을 요약해 들고 다니는 숫자 벡터, 곧 메모장이에요.","more":"코드의 h 예요. 처음에는 0 으로 채우고, 한 글자 읽을 때마다 새로 계산해요."},{"ko":"임베딩","en":"Embedding","say":"토큰 번호를 숫자 벡터로 바꾼 것, 곧 토큰의 지도 좌표예요.","more":"nn.Embedding(V, 64) 는 V 개 토큰마다 64칸 벡터를 하나씩 가진 표예요. 학습하며 값이 바뀌어요."},{"ko":"교차 엔트로피","en":"Cross-Entropy","say":"정답에 준 확률이 작을수록 커지는 벌점, -log(정답 확률)이에요.","more":"nn.CrossEntropyLoss 가 소프트맥스와 -log 를 함께 계산해요. 모든 시점의 평균이 손실이에요."},{"ko":"손실 함수","en":"Loss Function","say":"모델이 얼마나 틀렸는지 매기는 벌점이에요.","more":"학습은 손실을 줄이는 쪽으로 파라미터를 고치는 일이에요. 이 실습의 손실은 교차 엔트로피예요."},{"ko":"기울기 클리핑","en":"Gradient Clipping","say":"기울기 벡터가 너무 길면 방향은 두고 길이만 기준값으로 줄이는 방법이에요.","more":"clip_grad_norm_(..., 5.0) 은 길이를 5 이하로 잘라요. 기울기 폭발에 대한 강의의 처방이에요(N3 p.53)."},{"ko":"기울기 폭발","en":"Exploding Gradient","say":"1 보다 큰 수를 여러 번 곱하듯 기울기가 걷잡을 수 없이 커지는 문제예요.","more":"한 번의 이상한 큰 걸음이나 Inf, NaN 이 생겨요. 클리핑으로 막아요."},{"ko":"기울기 소실","en":"Vanishing Gradient","say":"1 보다 작은 수를 여러 번 곱하듯 먼 곳의 기울기가 0 에 가까워지는 문제예요.","more":"귓속말 전달 게임처럼 먼 앞 글자에 대한 학습 신호가 희미해져요. LSTM 게이트, 어텐션이 해결책이에요."},{"ko":"시간 역전파","en":"Backpropagation Through Time (BPTT)","say":"시점마다 펼친 RNN 위에서 뒤에서 앞으로 역전파하는 것이에요.","more":"loss.backward() 한 번이 64 시점을 거슬러 올라가며 같은 가중치에 기울기를 모두 더해요(N3 p.50)."},{"ko":"언어 모델","en":"Language Model (LM)","say":"앞 글을 보고 다음 토큰을 맞히는 모델이에요. 휴대폰 자판의 다음 단어 추천 같은 거예요.","more":"이 실습의 CharRNN 은 다음 글자를 맞히는 문자 단위 언어 모델이에요."},{"ko":"다음 토큰 예측","en":"Next Token Prediction","say":"지금까지의 토큰으로 바로 다음 토큰을 맞히는 과제예요.","more":"입력 x 를 한 칸 민 것이 정답 y 예요. 교수님: GPT 도 결국 이거예요."},{"ko":"퍼플렉서티","en":"Perplexity (PPL)","say":"다음 토큰을 고를 때 평균 몇 개 후보 사이에서 헷갈리는지 나타낸 숫자예요. 낮을수록 좋아요.","more":"PPL = exp(평균 교차 엔트로피). 예측 단위(글자, 서브워드)가 다르면 직접 비교할 수 없어요."},{"ko":"샘플링 온도","en":"Temperature","say":"생성할 때 얼마나 과감하게 뽑을지 정하는 손잡이예요.","more":"로짓을 온도로 나눠요. 낮으면 확률 높은 것만(안전, 반복), 높으면 드문 것도(다양, 엉망)."},{"ko":"로짓","en":"Logit","say":"소프트맥스에 넣기 전의 점수예요.","more":"self.out(h) 가 어휘 크기만큼의 로짓을 내고, 소프트맥스가 확률로 바꿔요."},{"ko":"소프트맥스","en":"Softmax","say":"점수를 모두 더해 1 이 되는 확률로 바꾸는 함수예요.","more":"torch.softmax(logits, dim=-1) 로 써요."},{"ko":"토크나이저","en":"Tokenizer","say":"글을 토큰으로 자르고 번호로 바꿔 주는 도구예요.","more":"Part 4 에서 글자 대신 KoGPT-2 의 서브워드 토크나이저로 바꾸고 나머지는 그대로 둬요."},{"ko":"어휘","en":"Vocabulary","say":"모델이 아는 토큰 종류의 목록이에요.","more":"글자 모델은 V = 1945, 서브워드 모델은 자주 나온 6000개 + <unk> 로 V = 6001 이에요."},{"ko":"서브워드","en":"Subword","say":"단어보다 작고 글자보다 큰 조각이에요.","more":"'재미있다' 를 '▁재미', '있', '다' 처럼 잘라요. 2주차 BPE 로 만든 조각이에요."},{"ko":"문자당 비트","en":"Bits per Character","say":"한 글자를 설명하는 데 모델이 평균 몇 비트가 필요한지예요. 낮을수록 좋아요.","more":"예측 단위가 다른 모델을 같은 자로 재는 방법이에요. 전체 음의 로그우도를 글자 수와 ln2 로 나눠요."},{"ko":"옵티마이저","en":"Optimizer","say":"기울기를 보고 파라미터를 실제로 고쳐 주는 도구예요.","more":"torch.optim.Adam 은 경사 하강법을 똑똑하게 바꾼 방법이에요. lr=2e-3 이 학습률이에요."}],"4":[{"ko":"자연어처리","en":"Natural Language Processing (NLP)","say":"컴퓨터가 사람의 말과 글을 다루게 하는 분야","more":"글을 토큰으로 자르고, 벡터로 바꾸고, 그 벡터로 다음 토큰을 맞혀요."},{"ko":"토큰","en":"Token","say":"글을 자른 레고 조각 하나","more":"모델이 읽는 가장 작은 단위예요. 단어일 수도, 단어의 조각(서브워드)일 수도 있어요."},{"ko":"어휘","en":"Vocabulary","say":"모델이 아는 토큰 종류의 목록","more":"어휘 크기를 V 라고 써요. 매 자리마다 V 개 후보 중 하나를 고르는 셈이에요."},{"ko":"순환 신경망","en":"Recurrent Neural Network (RNN)","say":"한 단어씩 읽으며 메모장에 요약을 고쳐 쓰는 신경망","more":"3주차에 배웠어요. 시점마다 같은 가중치를 다시 써서 은닉 상태를 갱신해요."},{"ko":"은닉 상태","en":"Hidden State","say":"지금까지 읽은 내용을 요약해 들고 다니는 숫자 벡터, 곧 메모장","more":"RNN 이 한 토큰을 읽을 때마다 새로 계산해요. 기호는 h 로 써요."},{"ko":"기울기 소실","en":"Vanishing Gradient","say":"귓속말 전달 게임처럼 기울기가 점점 희미해져 0 에 가까워지는 문제","more":"RNN 에서 먼 과거까지 학습 신호가 잘 가지 않는 이유예요. 어텐션이 이 문제를 비켜 가요."},{"ko":"시간 역전파","en":"Backpropagation Through Time (BPTT)","say":"시점마다 펼친 RNN 위에서 뒤에서 앞으로 역전파하기","more":"먼 과거로 갈수록 곱셈이 여러 번 쌓여서 기울기가 작아지거나 커져요."},{"ko":"시퀀스-투-시퀀스 모델","en":"Sequence-to-Sequence Model","say":"줄줄이 들어온 것을 읽고 줄줄이 내놓는 모델 틀","more":"인코더와 디코더 두 부분으로 되어 있어요. 번역, 요약, 대화, 음성 인식에 모두 써요."},{"ko":"인코더","en":"Encoder","say":"입력 문장을 끝까지 읽어 요약을 만드는 쪽","more":"2014년 원래 구조에서는 인코더가 RNN 이었고, 마지막 은닉 상태가 요약 벡터였어요."},{"ko":"디코더","en":"Decoder","say":"요약을 받아 답 문장을 한 토큰씩 만들어 내는 쪽","more":"디코더는 입력에 조건이 걸린 언어 모델이에요. 그래서 조건부 언어 모델이라고 불러요."},{"ko":"기계 번역","en":"Machine Translation (MT)","say":"한 언어 문장을 다른 언어 문장으로 바꾸는 과제","more":"4주차 내내 예제로 쓰는 과제예요. 입력 x 를 보고 출력 y 를 만들어요."},{"ko":"신경망 기계 번역","en":"Neural Machine Translation (NMT)","say":"신경망 하나로 통째로 학습하는 번역 방식","more":"2014년에 등장했어요. 2년 만에 수백 명이 십 년간 만든 통계 기반 시스템을 앞질렀어요."},{"ko":"언어 모델","en":"Language Model (LM)","say":"휴대폰 자판의 다음 단어 추천처럼 다음 토큰을 맞히는 모델","more":"3주차에 배웠어요. 문장의 확률을 조각조각 곱으로 나눠 써요."},{"ko":"조건부 언어 모델","en":"Conditional Language Model","say":"입력 문장 x 를 조건으로 붙인 언어 모델","more":"P(y|x) = P(y1|x) P(y2|y1, x) ... 처럼 매 자리마다 x 가 조건으로 계속 붙어요."},{"ko":"다음 토큰 예측","en":"Next Token Prediction","say":"지금까지의 토큰으로 바로 다음 토큰을 맞히는 과제","more":"교수님: 지금까지 토큰으로 다음 토큰을 예측하는 이것이 거의 모든 걸 결정해요."},{"ko":"교차 엔트로피","en":"Cross-Entropy","say":"정답 토큰에 준 확률의 -log 를 벌점으로 매기는 손실","more":"정답 확률이 1 이면 벌점 0, 0 에 가까우면 벌점이 아주 커져요."},{"ko":"손실 함수","en":"Loss Function","say":"틀린 정도를 매기는 벌점","more":"학습은 이 벌점이 작아지는 쪽으로 파라미터를 조금씩 고치는 일이에요."},{"ko":"종단간 학습","en":"End-to-End","say":"여러 부품을 따로 만들지 않고 하나의 신경망을 한 번에 학습하는 방식","more":"손실 하나를 정하고 역전파 한 번으로 디코더, 다리, 인코더까지 전부 고쳐요."},{"ko":"역전파","en":"Backpropagation","say":"틀린 책임을 뒤에서 앞으로 나눠 주기","more":"3주차 주제였어요. 손실의 기울기를 출력 쪽에서 입력 쪽으로 연쇄 법칙으로 계산해요."},{"ko":"교사 강요","en":"Teacher Forcing","say":"학습할 때 모델의 예측 대신 정답 단어를 다음 입력으로 넣어 주기","more":"선생님이 정답을 옆에서 알려 주는 셈이에요. 학습이 안정되고 시점끼리 병렬로 돌아가요."},{"ko":"노출 편향","en":"Exposure Bias","say":"학습 때는 정답을 보고, 시험 때는 자기 출력만 보는 데서 오는 어긋남","more":"교사 강요의 부작용이에요. 학습 환경과 실제 생성 환경이 달라서 생겨요."},{"ko":"추론","en":"Inference","say":"학습이 끝난 모델로 실제로 답을 만들어 보는 일","more":"이때는 정답을 모르니까 모델이 직전에 만든 토큰을 다음 입력으로 넣어요."},{"ko":"탐욕적 디코딩","en":"Greedy Decoding","say":"매 순간 확률이 가장 높은 토큰 하나만 고르기","more":"빠르고 단순하지만 한 번 잘못 고르면 되돌릴 수 없어요."},{"ko":"빔 서치","en":"Beam Search","say":"매 단계에서 좋은 후보 k 개를 남겨 두고 함께 넓히기","more":"탐욕의 단점을 줄여요. 전부 탐색하지는 않지만 꽤 좋은 근사예요."},{"ko":"빔 크기","en":"Beam Size","say":"빔 서치가 남겨 두는 후보 개수 k","more":"보통 5에서 10 을 써요. k = 1 이면 탐욕적 디코딩과 같아요."},{"ko":"길이 정규화","en":"Length Normalization","say":"끝난 후보들의 점수를 길이로 나눠서 비교하기","more":"로그 확률을 더하면 길수록 점수가 낮아져서, 나누지 않으면 짧은 문장만 뽑혀요."},{"ko":"블루 점수","en":"BLEU","say":"사람이 쓴 정답 문장과 n-gram 이 얼마나 겹치는지로 매기는 번역 점수","more":"1에서 4까지의 n-gram 정밀도를 곱하고, 너무 짧은 번역에는 페널티를 줘요."},{"ko":"간결성 페널티","en":"Brevity Penalty","say":"번역이 정답보다 너무 짧으면 점수를 깎는 항","more":"짧게 말해서 정밀도만 올리는 꼼수를 막아요."},{"ko":"엔그램","en":"n-gram","say":"바로 붙어 있는 토큰 n개 묶음","more":"2개면 bigram, 3개면 trigram 이에요. BLEU 는 1에서 4까지를 봐요."},{"ko":"정보 병목","en":"Information Bottleneck","say":"입력 전체가 고정 크기 벡터 하나를 지나가야 해서 생기는 막힘","more":"20단어 문장이든 200단어 문단이든 같은 칸 수의 벡터에 욱여넣어야 해요."},{"ko":"어텐션","en":"Attention","say":"필요한 곳을 골라 보는 장치. 점수를 매기고 가중 평균을 내요","more":"2015년에 나왔어요. 디코더가 매 단계마다 입력의 모든 자리를 다시 봐요."},{"ko":"셀프 어텐션","en":"Self-Attention","say":"한 문장이 자기 자신을 바라보는 어텐션","more":"2017년 트랜스포머의 핵심이에요. RNN 을 아예 빼 버려요."},{"ko":"트랜스포머","en":"Transformer","say":"어텐션만으로 만든 요즘 언어 모델의 기본 블록","more":"교수님: 이 트랜스포머를 좀 크게 쌓으면 그게 LLM 이에요."},{"ko":"대규모 언어 모델","en":"Large Language Model (LLM)","say":"트랜스포머 블록을 아주 많이 쌓아 크게 학습한 언어 모델","more":"ChatGPT 같은 모델이에요. 비전 트랜스포머까지 대부분 이 구조 위에 있어요."},{"ko":"병렬화","en":"Parallelization","say":"여러 계산을 한꺼번에 동시에 하기","more":"GPU 는 큰 행렬 곱을 한 번에 잘해요. 교수님: 패러럴이 핵심이에요."},{"ko":"기울기","en":"Gradient","say":"손실이 가장 빨리 커지는 방향과 그 가파름","more":"학습은 기울기의 반대 방향으로 한 걸음씩 내려가요."},{"ko":"문맥 벡터","en":"Context Vector","say":"이번 단계에 필요한 만큼만 뽑아 만든 요약 벡터","more":"인코더 은닉 상태들의 가중 평균이에요. 디코딩 단계마다 새로 만들어져요. 기호는 c_t 예요."},{"ko":"어텐션 점수","en":"Attention Score","say":"지금 디코더 상태와 각 입력 자리가 얼마나 관련 있는지 나타낸 날것 숫자","more":"가장 단순한 방법은 내적이에요. 합이 1 이 아니라서 그대로는 가중치로 못 써요."},{"ko":"어텐션 분포","en":"Attention Distribution","say":"점수를 소프트맥스에 넣어 합이 1 이 되게 만든 분포","more":"'내 주의가 어디로 얼마나 가는지' 를 그대로 읽을 수 있어요. 기호는 알파예요."},{"ko":"어텐션 가중치","en":"Attention Weight","say":"어텐션 분포의 각 칸 값. 그 자리를 얼마나 볼지 정해요","more":"모두 0 이상이고 다 더하면 1 이에요. 날카로우면 한 곳만, 평평하면 골고루 봐요."},{"ko":"가중합","en":"Weighted Sum","say":"값마다 가중치를 곱해서 모두 더한 것","more":"가중치의 합이 1 이면 가중 평균이에요. 문맥 벡터가 바로 인코더 상태들의 가중합이에요."},{"ko":"소프트맥스","en":"Softmax","say":"점수를 모두 더해 1 이 되는 확률 파이로 나누기","more":"각 점수에 exp 를 씌운 뒤 전체 합으로 나눠요. 2주차, 3주차에도 계속 나왔어요."},{"ko":"내적","en":"Dot Product","say":"두 화살표가 얼마나 같은 쪽을 보는지 재는 곱셈","more":"같은 자리끼리 곱해서 모두 더해요. 값이 크면 두 벡터가 비슷한 방향이에요."},{"ko":"쿼리","en":"Query","say":"지금 내가 무엇을 찾고 있는지를 담은 벡터","more":"디코더의 현재 상태가 쿼리예요. 쿼리가 바뀌면 어디를 볼지가 바뀌어요."},{"ko":"키","en":"Key","say":"나는 이런 정보를 갖고 있다고 광고하는 검색용 이름표 벡터","more":"쿼리와 키를 비교해서 점수를 만들어요. 사전의 색인 같은 역할이에요."},{"ko":"밸류","en":"Value","say":"내가 선택되면 실제로 건네줄 내용 벡터","more":"가중합에 들어가는 것은 키가 아니라 밸류예요. 2015년 어텐션에서는 키와 밸류가 같았어요."},{"ko":"정렬","en":"Alignment","say":"원문의 어떤 단어가 번역문의 어떤 단어에 대응하는지 이어 주는 것","more":"통계 기반 번역에서는 따로 모델을 만들어야 했는데, 어텐션은 학습하다 저절로 배워요."},{"ko":"해석 가능성","en":"Interpretability","say":"모델이 어디를 보고 판단했는지 사람이 알아볼 수 있는 성질","more":"어텐션 가중치를 그림으로 찍으면 모델이 어디를 봤는지 보여요. 딥러닝에서는 드문 일이에요."},{"ko":"다층 퍼셉트론","en":"Multi-Layer Perceptron (MLP)","say":"뉴런 층을 여러 겹 쌓은 가장 기본 신경망","more":"3주차에 배웠어요. Bahdanau 방식 점수 함수가 작은 MLP 를 써요."},{"ko":"하이퍼볼릭 탄젠트","en":"tanh","say":"어떤 수든 -1과 1 사이로 눌러 주는 S자 함수","more":"3주차에 배운 활성화 함수예요. 어텐션의 예측 단계와 Bahdanau 점수 함수에 나와요."},{"ko":"크로스 어텐션","en":"Cross-Attention","say":"쿼리는 한쪽 시퀀스, 키와 밸류는 다른 쪽 시퀀스에서 오는 어텐션","more":"Part 2 에서 배운 2015년 어텐션이 바로 이것이에요. 디코더가 인코더를 봐요."},{"ko":"스케일드 닷프로덕트 어텐션","en":"Scaled Dot-Product Attention","say":"내적 점수를 루트 d_k 로 나눈 뒤 소프트맥스를 쓰는 어텐션","more":"트랜스포머가 쓰는 방식이에요. 나누기 한 번이 학습을 살려요."},{"ko":"순열 등변성","en":"Permutation Equivariance","say":"입력 순서를 바꾸면 출력도 똑같이 순서만 바뀌는 성질","more":"셀프 어텐션이 순서를 전혀 모른다는 뜻이에요. 그래서 위치 인코딩이 필요해요."},{"ko":"위치 인코딩","en":"Positional Encoding","say":"몇 번째 자리인지를 알려 주는 벡터를 임베딩에 더해 주기","more":"셀프 어텐션의 배리어 1(순서 없음)을 고치는 부품이에요."},{"ko":"사인 코사인 위치 인코딩","en":"Sinusoidal Positional Encoding","say":"sin 과 cos 파도로 만든, 학습하지 않는 위치 벡터","more":"2017년 원래 논문이 쓴 방식이에요. 학습 파라미터가 0 개예요."},{"ko":"로프","en":"RoPE","say":"쿼리와 키를 위치에 비례한 각도만큼 회전시키는 위치 방식","more":"점수가 두 자리의 상대 거리 i - j 에만 의존하게 돼요. 요즘 LLM 이 거의 다 써요."},{"ko":"위치별 피드포워드 신경망","en":"Position-wise Feed-Forward Network (FFN)","say":"자리마다 똑같이 적용하는 2층짜리 작은 신경망","more":"배리어 2(비선형성 없음)를 고쳐요. 가운데 차원이 보통 4d 라서 파라미터가 많아요."},{"ko":"인과 마스킹","en":"Causal Masking","say":"미래 자리의 점수를 소프트맥스 전에 마이너스 무한으로 바꾸기","more":"배리어 3(미래를 훔쳐봄)을 고쳐요. 가중치가 정확히 0 이 돼요."},{"ko":"자기회귀","en":"Autoregressive","say":"앞에서 만든 토큰을 보고 다음 토큰을 하나씩 만드는 방식","more":"GPT 같은 모델이 이렇게 글을 써요. 그래서 미래를 보면 안 돼요."},{"ko":"임베딩","en":"Embedding","say":"토큰을 숫자 벡터로 바꾼 것. 단어의 지도 좌표","more":"위치 인코딩은 이 임베딩에 더해져요."},{"ko":"파라미터","en":"Parameter","say":"학습하면서 바뀌는 숫자. 모델이 기억을 저장하는 자리","more":"W^Q, W^K, W^V 가 파라미터예요. 모든 자리에서 같은 것을 나눠 써요."},{"ko":"비선형성","en":"Nonlinearity","say":"곧은 직선이 아닌 구부러진 변환","more":"이것이 없으면 층을 아무리 쌓아도 결국 한 층과 같아요."},{"ko":"렐루","en":"ReLU","say":"음수는 0 으로 만들고 양수는 그대로 두는 함수","more":"FFN 가운데에 들어가서 비선형성을 만들어요. 3주차에 배웠어요."},{"ko":"멀티 헤드 어텐션","en":"Multi-Head Attention (MHA)","say":"전체 차원을 h 조각으로 나눠 여러 관점에서 동시에 어텐션하기","more":"Part 4 에서 배워요. 계산량은 늘지 않아요."},{"ko":"잔차 연결","en":"Residual Connection","say":"층의 입력을 층의 출력에 그대로 더해 주는 지름길","more":"Part 4 에서 배워요. 깊게 쌓아도 학습이 되게 해 줘요."},{"ko":"층 정규화","en":"Layer Normalization (LayerNorm)","say":"한 토큰의 숫자들을 평균 0, 분산 1 로 맞춰 주기","more":"Part 4 에서 배워요. 값이 폭주하지 않게 잡아 줘요."},{"ko":"버트","en":"BERT","say":"앞뒤를 다 보는 인코더 방식 언어 모델","more":"마스킹을 하지 않는 쪽이에요. 위치 벡터를 학습해서 써요."},{"ko":"지피티","en":"GPT","say":"앞만 보고 다음 토큰을 만드는 디코더 방식 언어 모델","more":"인과 마스킹을 쓰는 쪽이에요. 자기회귀로 글을 써요."},{"ko":"헤드","en":"Head","say":"어텐션을 한 번 보는 행위 하나","more":"헤드마다 자기만의 W^Q, W^K, W^V 를 가져서 문법, 가까운 문맥처럼 서로 다른 것을 봐요."},{"ko":"항등 경로","en":"Identity Path","say":"아무 계산도 하지 않고 그대로 지나가는 길","more":"야코비안이 I + 함수의 미분이 되어서, 기울기가 곱해져도 1 이 남아요."},{"ko":"이차 비용","en":"Quadratic Cost","say":"길이가 2배면 일이 4배가 되는 비용","more":"셀프 어텐션은 n x n 점수 표를 만들기 때문에 계산과 메모리가 n 의 제곱으로 커져요."},{"ko":"기울기 폭발","en":"Exploding Gradient","say":"기울기가 곱해지다 너무 커져서 학습이 터지는 문제","more":"기울기 소실의 반대쪽 문제예요. 잔차 연결과 LayerNorm 이 함께 잡아 줘요."},{"ko":"야코비안","en":"Jacobian","say":"벡터를 벡터로 보내는 함수의 미분을 표로 적은 것","more":"잔차 연결이 있으면 야코비안이 I + 함수의 미분 모양이 돼요. 3주차에 나왔어요."},{"ko":"장단기 메모리","en":"LSTM","say":"게이트를 달아 기억을 오래 들고 가게 만든 RNN","more":"트랜스포머가 나오기 전까지 가장 강한 시퀀스 모델이었어요."},{"ko":"합성곱 신경망","en":"Convolutional Neural Network (CNN)","say":"작은 필터를 훑으며 무늬를 찾아내는 신경망","more":"헤드를 CNN 의 필터 여러 개에 비유할 수 있어요. WMT 비교 표에도 나와요."},{"ko":"학습률","en":"Learning Rate","say":"한 걸음의 보폭","more":"Post-LN 은 처음에 보폭을 천천히 키우는 워밍업이 없으면 학습이 터져요."},{"ko":"사전 학습","en":"Pre-training","say":"아주 많은 글로 미리 크게 학습해 두는 단계","more":"다음 주에 배워요. 블록은 그대로이고 학습 데이터만 커져요."},{"ko":"시퀀스-투-시퀀스","en":"seq2seq","say":"줄줄이 들어와서 줄줄이 나가는 구조예요.","more":"읽는 쪽과 쓰는 쪽, 신경망 두 개를 이어 붙여 만들어요. 2014년에 나왔어요."},{"ko":"텐서","en":"Tensor","say":"숫자를 여러 줄, 여러 칸으로 담은 묶음이에요. shape 으로 크기를 읽어요."}],"4L":[{"ko":"어텐션","en":"Attention","say":"필요한 곳을 골라 보는 장치. 점수를 매기고 가중 평균을 내요.","more":"세 단계예요. 점수 매기기, 소프트맥스로 합이 1 인 가중치 만들기, 밸류를 가중합 하기(N4 p.21-24)."},{"ko":"셀프 어텐션","en":"Self-Attention","say":"한 문장이 자기 자신을 바라보는 어텐션이에요.","more":"쿼리, 키, 밸류가 모두 같은 시퀀스에서 나와요. 2017년 트랜스포머의 핵심이에요(N4 p.33)."},{"ko":"크로스 어텐션","en":"Cross-Attention","say":"쿼리는 한 시퀀스에서, 키와 밸류는 다른 시퀀스에서 오는 어텐션이에요.","more":"2015년 번역 어텐션이 이것이에요. 교수님은 이 노트북 Part 1 이 크로스 어텐션 개념이라고 했어요."},{"ko":"쿼리","en":"Query","say":"지금 내가 무엇을 찾는지를 담은 벡터, 곧 질문이에요.","more":"코드의 query 예요. 쿼리가 바뀌면 어디를 볼지가 바뀌어요."},{"ko":"키","en":"Key","say":"나는 이런 정보를 갖고 있다고 광고하는 이름표 벡터예요.","more":"쿼리와 키를 내적해서 점수를 만들어요. 사전의 색인 같은 역할이에요."},{"ko":"밸류","en":"Value","say":"내가 뽑히면 실제로 건네줄 내용 벡터예요.","more":"가중합에 들어가는 것은 키가 아니라 밸류예요. 출력은 밸류들의 가중 평균이에요."},{"ko":"어텐션 점수","en":"Attention Score","say":"쿼리와 키가 얼마나 맞는지 나타낸 날것 숫자예요.","more":"코드의 scores 예요. 합이 1 이 아니라서 그대로는 가중치로 못 써요."},{"ko":"어텐션 분포","en":"Attention Distribution","say":"점수를 소프트맥스에 넣어 합이 1 이 되게 만든 분포예요.","more":"행마다 더하면 1 이에요. 그래서 '내 주의가 어디로 얼마나 가는지' 로 읽을 수 있어요."},{"ko":"어텐션 가중치","en":"Attention Weight","say":"어텐션 분포의 각 칸 값. 그 자리를 얼마나 볼지 정해요.","more":"모두 0 이상이고 다 더하면 1 이에요. 코드의 weights, A 가 이것이에요."},{"ko":"가중합","en":"Weighted Sum","say":"값마다 가중치를 곱해서 모두 더한 것이에요.","more":"가중치의 합이 1 이면 가중 평균이에요. 어텐션의 출력이 바로 밸류들의 가중합이에요."},{"ko":"소프트맥스","en":"Softmax","say":"점수를 모두 더해 1 이 되는 확률 파이로 나누는 함수예요.","more":"각 점수에 exp 를 씌운 뒤 전체 합으로 나눠요. 점수가 크면 거의 한 곳만 보게 돼요."},{"ko":"내적","en":"Dot Product","say":"두 화살표가 얼마나 같은 쪽을 보는지 재는 곱셈이에요.","more":"같은 자리끼리 곱해서 모두 더해요. 어텐션 점수의 가장 단순한 계산법이에요."},{"ko":"스케일드 닷프로덕트 어텐션","en":"Scaled Dot-Product Attention","say":"내적 점수를 키 차원의 제곱근으로 나눈 뒤 소프트맥스를 쓰는 어텐션이에요.","more":"d_k 가 커지면 점수의 표준편차가 루트 d_k 만큼 커져서, 나눠 주지 않으면 소프트맥스가 포화돼요(N4 p.38)."},{"ko":"순열 등변성","en":"Permutation Equivariance","say":"입력 순서를 섞으면 출력도 똑같이 섞일 뿐, 값 자체는 그대로인 성질이에요.","more":"셀프 어텐션의 첫 번째 장벽이에요. 순서가 계산 안에 없다는 뜻이라 위치 인코딩이 필요해요(N4 p.40)."},{"ko":"위치 인코딩","en":"Positional Encoding","say":"몇 번째 자리인지를 알려 주는 벡터를 토큰 벡터에 더해 주는 것이에요.","more":"셀프 어텐션에는 순서 개념이 없어서, 순서를 입력 쪽에 넣어 줘요."},{"ko":"사인 코사인 위치 인코딩","en":"Sinusoidal Positional Encoding","say":"사인과 코사인 물결로 위치 벡터를 만드는 방식이에요.","more":"2017년 원논문의 방식이에요. 차원마다 파장이 달라서 위치마다 무늬가 달라요. 학습할 파라미터가 없어요."},{"ko":"위치별 피드포워드 신경망","en":"Position-wise Feed-Forward Network (FFN)","say":"토큰마다 따로 적용하는 2층 신경망이에요.","more":"여기서는 자리끼리 섞이지 않아요. 어텐션은 정보를 옮기고, 이 층이 정보를 바꿔요(N4 p.42)."},{"ko":"인과 마스킹","en":"Causal Masking","say":"미래 자리의 점수를 소프트맥스 전에 음의 무한대로 만들어 못 보게 막는 것이에요.","more":"언어 모델이 정답을 미리 훔쳐보지 못하게 해요. 마스크는 반드시 소프트맥스 전에 걸어요(N4 p.43)."},{"ko":"자기회귀","en":"Autoregressive","say":"자기가 방금 만든 토큰을 다시 입력으로 넣어 다음 토큰을 만드는 방식이에요.","more":"GPT 계열이 이 방식이에요. 그래서 인과 마스킹이 꼭 필요해요."},{"ko":"멀티 헤드 어텐션","en":"Multi-Head Attention (MHA)","say":"전체 차원을 h 조각으로 나눠 서로 다른 관점으로 동시에 보는 어텐션이에요.","more":"교수님: 차원을 키우는 게 아니라 h 로 나눠서 보는 것이라 계산량은 똑같아요(N4 p.47-48)."},{"ko":"헤드","en":"Head","say":"어텐션을 한 번 보는 행위 하나예요.","more":"교수님 비유로 합성곱의 필터 같아요. 어떤 헤드는 문법을, 어떤 헤드는 가까운 문맥을 봐요."},{"ko":"잔차 연결","en":"Residual Connection","say":"층의 입력을 층의 출력에 그대로 더해 주는 지름길이에요.","more":"기울기가 곧장 앞층까지 흐르는 항등 경로가 생겨요. 깊게 쌓으려면 꼭 필요해요(N4 p.49)."},{"ko":"층 정규화","en":"Layer Normalization (LayerNorm)","say":"토큰 하나의 숫자들을 평균 0, 분산 1 로 고르게 만드는 것이에요.","more":"토큰끼리도, 배치끼리도 섞지 않아요. 요즘 모델은 층 앞에 두는 Pre-LN 방식을 써요(N4 p.50-51)."},{"ko":"트랜스포머","en":"Transformer","say":"어텐션만으로 만든 요즘 언어 모델의 기본 블록이에요.","more":"교수님: 트랜스포머를 좀 크게 쌓으면 그게 LLM 이에요. 이 실습에서 직접 조립해요."},{"ko":"병렬화","en":"Parallelization","say":"여러 계산을 한꺼번에 동시에 하기예요.","more":"셀프 어텐션은 행렬 곱 한 번으로 모든 자리를 함께 계산해요. 교수님: 패러럴이 핵심이에요."},{"ko":"텐서","en":"Tensor","say":"PyTorch 와 NumPy 가 쓰는 숫자 배열(벡터, 행렬, 그 이상)이에요.","more":"torch.randn(2, 7, 64) 는 2 x 7 x 64 텐서예요. .shape 로 모양을 봐요."},{"ko":"모양","en":"Shape","say":"텐서가 몇 줄 몇 칸인지 적은 튜플이에요. (5, 16) 처럼 써요.","more":"노트북이 계속 shape 를 찍어요. 3주차 실습에서 배운 가장 쓸모 있는 디버깅 습관이에요."},{"ko":"기울기","en":"Gradient","say":"값을 조금 바꾸면 결과가 얼마나, 어느 쪽으로 바뀌는지 알려 주는 숫자예요.","more":"기울기가 0 에 가까우면 그 층은 배우지 못해요. 포화된 소프트맥스가 그런 상태예요."},{"ko":"기울기 소실","en":"Vanishing Gradient","say":"기울기가 점점 희미해져 0 에 가까워지는 문제예요.","more":"3주차 RNN 의 문제였어요. 포화된 소프트맥스도 같은 증상을 만들어요."},{"ko":"파라미터","en":"Parameter","say":"모델이 학습하면서 값을 고쳐 나가는 숫자들이에요.","more":"가중치 행렬과 편향 항이 파라미터예요. 개수를 세면 모델의 크기를 알 수 있어요."},{"ko":"언어 모델","en":"Language Model (LM)","say":"앞 글을 보고 다음 토큰을 맞히는 모델이에요.","more":"3주차에 배웠어요. 언어 모델은 미래를 보면 안 되니까 인과 마스킹이 필요해요."},{"ko":"항등 경로","en":"Identity Path","say":"잔차 연결이 만들어 주는, 아무 변형 없이 통과하는 길이에요.","more":"기울기가 이 길을 타고 곧장 앞층까지 가요. 그래서 96층도 학습이 돼요."},{"ko":"임베딩","en":"Embedding","say":"토큰 번호를 숫자 벡터로 바꾼 것, 곧 토큰의 지도 좌표예요.","more":"nn.Embedding(11, 64) 은 토큰 11종류마다 64칸 벡터를 하나씩 가진 표예요."},{"ko":"어휘","en":"Vocabulary","say":"모델이 아는 토큰 종류의 목록이에요.","more":"이 과제의 어휘는 숫자 0에서 9 까지 열 개에 구분자 하나를 더해 11 이에요."},{"ko":"토큰","en":"Token","say":"모델이 읽는 가장 작은 단위예요.","more":"여기서는 숫자 한 글자가 토큰이에요. Part 5 에서는 DistilBERT 의 서브워드가 토큰이에요."},{"ko":"토크나이저","en":"Tokenizer","say":"글을 토큰으로 자르고 번호로 바꿔 주는 도구예요.","more":"DistilBERT 의 토크나이저는 문장 앞뒤에 [CLS] 와 [SEP] 라는 특수 토큰을 붙여요."},{"ko":"다음 토큰 예측","en":"Next Token Prediction","say":"지금까지의 토큰으로 바로 다음 토큰을 맞히는 과제예요.","more":"입력을 한 칸 민 것이 정답이에요. 교수님: GPT 도 결국 이거예요."},{"ko":"교차 엔트로피","en":"Cross-Entropy","say":"정답에 준 확률이 작을수록 커지는 벌점, -log(정답 확률)이에요.","more":"후보가 10개인데 아무것도 모르면 손실이 ln(10) = 2.303 이에요. 이게 찍기 수준이에요."},{"ko":"손실 함수","en":"Loss Function","say":"모델이 얼마나 틀렸는지 매기는 벌점이에요.","more":"학습은 이 벌점이 작아지는 쪽으로 파라미터를 고치는 일이에요."},{"ko":"옵티마이저","en":"Optimizer","say":"기울기를 보고 파라미터를 실제로 고쳐 주는 도구예요.","more":"torch.optim.AdamW 는 경사 하강법을 똑똑하게 바꾼 방법이에요. lr=3e-3 이 학습률이에요."},{"ko":"해석 가능성","en":"Interpretability","say":"모델이 어디를 보고 판단했는지 사람이 알아볼 수 있는 성질이에요.","more":"어텐션 그림이 대표적이에요. 다만 '어디서 가져왔나' 이지 '왜 그렇게 답했나' 는 아니에요."},{"ko":"정렬","en":"Alignment","say":"어떤 자리가 어떤 자리에 대응하는지 이어 주는 것이에요.","more":"아무도 가르쳐 주지 않았는데 어텐션이 학습하다 저절로 배워요(N4 p.26)."},{"ko":"버트","en":"BERT","say":"양쪽을 다 보는 인코더 방식의 사전 학습 언어 모델이에요.","more":"이 실습에서는 가볍게 줄인 DistilBERT 를 써요. 다음 주 5주차 주제예요."}]};
